insert into public.curriculum_levels (version_id, id, code, name, sort_order, cycle, equivalence, entry_age, exit_age, entry_profile, exit_profile, source_row)
values ('ht-malla-2026-06', 'step-3', 'S3', 'Step 3', 3, 'Ciclo II: preescolar', 'Prejardín', '3 años', '4 años', 'Niño o niña que llega con autonomía básica, lenguaje oral emergente, curiosidad y capacidad de juego, pero aún requiere mediación para regular emociones, sostener atención, organizar acciones, negociar turnos y expresar ideas con claridad.', 'Niño o niña que participa de forma más autónoma y propositiva, narra experiencias con orden básico, clasifica con uno o dos criterios, explora patrones simples, representa ideas con lenguajes artísticos, reconoce emociones, coopera y participa en acuerdos de aula.', 10)
