insert into public.curriculum_levels (version_id, id, code, name, sort_order, cycle, equivalence, entry_age, exit_age, entry_profile, exit_profile, source_row)
values ('ht-malla-2026-06', 'kinder', 'K', 'Kínder', 4, 'Ciclo II: preescolar', 'Jardín', '4 años', '5 años', 'Niño o niña con lenguaje oral más claro, autonomía cotidiana en desarrollo, interés por cuentos, letras, números, juego simbólico, construcción y proyectos. Requiere acompañamiento para autorregularse, sostener atención, resolver conflictos y organizar tareas con mayor precisión.', 'Niño o niña que participa activamente en proyectos, narra con mayor estructura, formula preguntas, representa ideas mediante dibujos, marcas o escrituras emergentes, resuelve retos lógicos con material concreto, coopera, sigue acuerdos y asume responsabilidades acordes a su edad.', 14)
