insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-S1-P1', 'step-1', 1, 'Periodo I', 'S1.1', 'Descubro y exploro mi entorno', '{"alcance":"Favorecer la exploración del entorno cercano mediante experiencias sensoriales, observación directa, vínculo seguro, comunicación inicial y autonomía emergente.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños reconocen su cuerpo, construyen vínculos seguros con adultos y pares, se sienten acogidos en el aula y participan en experiencias sensoriales de contacto afectivo.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños expresan necesidades, emociones e intereses mediante gestos, miradas, balbuceos, palabras iniciales, movimientos, sonidos y respuestas corporales.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños exploran libremente el entorno cercano, manipulan objetos, descubren texturas, sonidos, colores y movimientos, y experimentan con su cuerpo como primer medio de conocimiento.","indagar":"Observar movimientos espontáneos, objetos que llaman su atención, respuestas sensoriales, búsqueda del adulto, formas iniciales de comunicación, preferencias de materiales y apoyos requeridos.","proyectar":"Diseñar ambientes y provocaciones sensoriales seguras con objetos manipulables, texturas, sonidos, colores, materiales grandes, zonas de baja sobrecarga, anticipación, tiempos flexibles y alternativas de participación.","vivir":"Propiciar la exploración de objetos reales, texturas, cuentos cortos, canciones, túneles, desplazamientos con apoyo, dáctilopintura, garabateo libre y juegos corporales que fortalezcan vínculo, comunicación y autonomía emergente.","valorar":"Interpretar exploraciones, señales comunicativas, vínculos, preferencias sensoriales y avances en movimiento para ajustar apoyos, materiales, tiempos y nuevas provocaciones según intereses y ritmos individuales.","juego":"Tema: juego de apego, permanencia y exploración libre. Competencia: busca, toma, entrega, imita y responde al adulto. Avance: acepta gradualmente rutinas y espacios. Evidencia: registro de adaptación, fotografías de juego y observación narrativa.","exploracion":"Tema: entorno cercano, objetos seguros, texturas, sonidos y movimiento. Competencia: explora con cuerpo y sentidos. Avance: reconoce aula, parque, materiales y personas significativas. Evidencia: secuencia fotográfica y portafolio sensorial.","literatura":"Tema: canciones de bienvenida, cuentos cortos, onomatopeyas y partes del cuerpo. Competencia: atiende voces, gestos e imágenes. Avance: anticipa canciones o responde con mirada, gesto, sonido o palabra inicial. Evidencia: registro anecdótico.","arte":"Tema: dáctilopintura, garabateo libre, huellas y texturas. Competencia: explora materiales y deja marcas. Avance: manipula con curiosidad y tolerancia sensorial progresiva. Evidencia: producción sensorial y fotografía comentada.","nucleos":"Exploración sensorial; cuerpo y movimiento; comunicación emergente; arte y estética; vínculo seguro; educación emocional básica","saberes":"Texturas, temperaturas, olores, sonidos; dentro/fuera; arriba/abajo; partes del cuerpo; nombres cotidianos de objetos, familia y prendas; sonidos ambientales y onomatopeyas.","competencias":"Explora con cuerpo y sentidos; expresa necesidades con gestos o palabras; participa en rutinas con apoyo; construye vínculo con adultos y pares.","evidencias":"Registro narrativo; fotografías de exploración; observación directa; portafolio sensorial.","dua":"Anticipación visual; objeto transicional; ingreso gradual; rincón de calma; reducción de estímulos; materiales grandes y seguros.","caribe":"Exploración sensorial del aula, patio y espacios cercanos en el clima cálido de Barranquilla, reconociendo brisa, sombra, sonidos, texturas, agua, objetos cotidianos y presencia afectiva de adultos significativos.","gire":"Favorecer búsqueda del adulto como base de seguridad, desplazamientos acompañados, uso de objetos grandes y seguros, reconocimiento gradual de espacios permitidos y cuidado ante caídas, golpes o sobrecarga sensorial.","procesos":"Vínculo seguro con adultos y pares; exploración sensorial del entorno; comunicación inicial mediante gestos, miradas, sonidos y movimientos; adaptación progresiva a rutinas y espacios; autonomía emergente en desplazamientos y elección de objetos.","ambientes":"Espacios ventilados, con sombra, hidratación disponible, materiales higienizados, zonas de baja sobrecarga sensorial, pisos seguros, acompañamiento corporal respetuoso y rincón de calma para adaptación.","indicadores":"Señala, mira, toma o entrega objetos; responde a voces, canciones o cuentos breves; explora texturas y sonidos; busca al adulto para seguridad; se desplaza con mayor confianza; participa en rutinas con apoyo.","documentacion":"Registro narrativo de adaptación, fotografías comentadas, portafolio sensorial y observación directa. Alertas: rechazo persistente a la interacción o al contacto con el entorno, ausencia de respuesta a voces o estímulos habituales, dificultad marcada para alimentarse, descansar, desplazarse o regularse; activar diálogo con familia y acompañamiento institucional.","emocional":"Vínculo seguro; reconocimiento inicial de emociones básicas; búsqueda del adulto para seguridad y consuelo.","familia":"Enviar objeto significativo; compartir fotos o relatos de nuevas habilidades; reforzar canciones o rituales de calma en casa.","observacion":"Se observa cómo las niñas y los niños señalan, miran, toman o entregan objetos, se desplazan con mayor seguridad, buscan al adulto como base de seguridad y responden a canciones o cuentos breves. Estas evidencias permiten valorar avances en vínculo, comunicación emergente, exploración sensorial y participación. A partir de lo observado, se ajustan apoyos, mediaciones o nuevas provocaciones según intereses, necesidades y ritmos individuales."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños reconocen su cuerpo, construyen vínculos seguros con adultos y pares, se sienten acogidos en el aula y participan en experiencias sensoriales de contacto afectivo."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños expresan necesidades, emociones e intereses mediante gestos, miradas, balbuceos, palabras iniciales, movimientos, sonidos y respuestas corporales."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños exploran libremente el entorno cercano, manipulan objetos, descubren texturas, sonidos, colores y movimientos, y experimentan con su cuerpo como primer medio de conocimiento."}]'::jsonb, '{"juego":{"tema":"juego de apego, permanencia y exploración libre.","competencia":"busca, toma, entrega, imita y responde al adulto.","avance":"acepta gradualmente rutinas y espacios.","evidencia":"registro de adaptación, fotografías de juego y observación narrativa."},"exploracion":{"tema":"entorno cercano, objetos seguros, texturas, sonidos y movimiento.","competencia":"explora con cuerpo y sentidos.","avance":"reconoce aula, parque, materiales y personas significativas.","evidencia":"secuencia fotográfica y portafolio sensorial."},"literatura":{"tema":"canciones de bienvenida, cuentos cortos, onomatopeyas y partes del cuerpo.","competencia":"atiende voces, gestos e imágenes.","avance":"anticipa canciones o responde con mirada, gesto, sonido o palabra inicial.","evidencia":"registro anecdótico."},"arte":{"tema":"dáctilopintura, garabateo libre, huellas y texturas.","competencia":"explora materiales y deja marcas.","avance":"manipula con curiosidad y tolerancia sensorial progresiva.","evidencia":"producción sensorial y fotografía comentada."}}'::jsonb, 2)
