insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-S1-P2', 'step-1', 2, 'Periodo II', 'S1.2', 'Mi cuerpo se cuida y se comunica', '{"alcance":"Fortalecer el reconocimiento del cuerpo propio, las rutinas de cuidado, higiene y alimentación, promoviendo autonomía inicial y comunicación verbal y no verbal de necesidades, emociones y preferencias.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños participan en rutinas de cuidado, higiene y alimentación que fortalecen seguridad, autonomía inicial, confianza corporal y sentido de pertenencia al grupo.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños comunican necesidades, emociones, preferencias, incomodidades o solicitudes de ayuda mediante gestos, palabras iniciales, movimientos y señales corporales.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños exploran su cuerpo, objetos de cuidado, rutinas, colores, funciones de objetos y nociones espaciales simples desde el juego, la imitación y la vida práctica.","indagar":"Observar la participación en rutinas de higiene, alimentación y vestido, las formas de pedir ayuda, expresar incomodidad, reconocer objetos de cuidado y responder a secuencias cotidianas.","proyectar":"Diseñar ambientes de vida práctica, secuencias visuales de rutinas, objetos reales de higiene y alimentación, juegos de imitación, apoyos de transición y mediaciones que favorezcan comunicación, autonomía y seguridad corporal.","vivir":"Propiciar juegos de cuidado, canciones corporales, clasificación de objetos de higiene y alimentación, praxias lúdicas, experimentación con figuras y tamaños, y rutinas de vida práctica acompañadas.","valorar":"Interpretar la participación en rutinas, comunicación de necesidades, tolerancia a transiciones y autonomía emergente para ajustar apoyos visuales, modelamientos, tiempos y continuidad familia-escuela.","juego":"Tema: imitación de rutinas de cuidado. Competencia: participa en lavar, guardar, comer, vestir o pedir ayuda. Avance: realiza pequeñas acciones con apoyo. Evidencia: fotografías de vida práctica y registro de rutinas.","exploracion":"Tema: objetos de higiene, alimentación, ropa y cuidado corporal. Competencia: reconoce funciones y relaciones simples. Avance: clasifica o usa objetos según contexto. Evidencia: observación directa y diálogo con familias.","literatura":"Tema: canciones corporales, cuentos de higiene y secuencias de rutina. Competencia: asocia palabra, gesto y acción. Avance: anticipa partes de la rutina mediante imágenes, sonidos o palabras. Evidencia: registro narrativo.","arte":"Tema: cuerpo, colores, figuras y marcas en distintos soportes. Competencia: representa sensaciones y acciones con huellas, modelado o garabateo. Avance: elige materiales y participa con intención. Evidencia: portafolio artístico.","nucleos":"Cuerpo; higiene; alimentación; pedir ayuda; rutinas; señales corporales; cortesía inicial.","saberes":"Partes del cuerpo; higiene; ropa; alimentación; rutinas de cuidado; funciones de objetos; colores primarios; nociones dentro/fuera, arriba/abajo.","competencias":"Participa en rutinas de cuidado; expresa necesidades; reconoce partes del cuerpo y objetos cotidianos; inicia autonomía en rutinas básicas.","evidencias":"Registro de rutinas; fotografías de vida práctica; observación directa; diálogo con familias.","dua":"Pictogramas de rutinas; modelamiento verbal; secuencias visuales; apoyo físico seguro; tiempos flexibles.","caribe":"Rutinas de cuidado corporal contextualizadas al Caribe: lavado de manos, hidratación frecuente, cambio de ropa si hay calor o sudoración, alimentación tranquila y cuidado del cuerpo en ambientes cálidos.","gire":"Anticipar transiciones con apoyos visuales, reconocer objetos seguros de higiene, pedir ayuda ante incomodidad, seguir secuencias simples de cuidado y mantener acompañamiento adulto en alimentación, aseo y desplazamientos.","procesos":"Reconocimiento del cuerpo propio; participación en rutinas de cuidado, higiene y alimentación; comunicación de necesidades e incomodidades; uso funcional de objetos cotidianos; autonomía inicial en acciones de vida práctica.","ambientes":"Ambiente limpio, ventilado, con acceso a agua, rutinas tranquilas de alimentación, higiene acompañada, objetos reales seguros, pictogramas, tiempos flexibles y cuidado respetuoso del cuerpo.","indicadores":"Participa en lavar, guardar, comer o vestir con apoyo; expresa hambre, sueño, incomodidad o necesidad de ayuda; reconoce objetos de cuidado; anticipa rutinas con imágenes, gestos o palabras; acepta transiciones con acompañamiento.","documentacion":"Registro de rutinas, fotografías de vida práctica, diálogo con familias y observador individual. Alertas: cambios persistentes en alimentación, sueño, higiene, irritabilidad, rechazo sostenido a rutinas o dificultad para comunicar necesidades; activar conversación con familia y seguimiento pedagógico.","emocional":"Autocuidado; confianza corporal; expresión de necesidad, incomodidad, hambre, sueño o cansancio.","familia":"Reforzar rutinas de lavado de manos, guardar juguetes, nombrar emociones básicas y pedir ayuda.","observacion":"Se observa cómo las niñas y los niños participan en acciones de lavar, guardar, comer, vestir o pedir ayuda; expresan necesidades mediante gestos, sonidos o palabras; y aceptan transiciones con acompañamiento. Estas evidencias permiten valorar avances en autonomía inicial, seguridad corporal, comunicación funcional y participación en rutinas. A partir de lo observado, se ajustan apoyos visuales, tiempos, modelamientos o mediaciones familiares."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños participan en rutinas de cuidado, higiene y alimentación que fortalecen seguridad, autonomía inicial, confianza corporal y sentido de pertenencia al grupo."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños comunican necesidades, emociones, preferencias, incomodidades o solicitudes de ayuda mediante gestos, palabras iniciales, movimientos y señales corporales."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños exploran su cuerpo, objetos de cuidado, rutinas, colores, funciones de objetos y nociones espaciales simples desde el juego, la imitación y la vida práctica."}]'::jsonb, '{"juego":{"tema":"imitación de rutinas de cuidado.","competencia":"participa en lavar, guardar, comer, vestir o pedir ayuda.","avance":"realiza pequeñas acciones con apoyo.","evidencia":"fotografías de vida práctica y registro de rutinas."},"exploracion":{"tema":"objetos de higiene, alimentación, ropa y cuidado corporal.","competencia":"reconoce funciones y relaciones simples.","avance":"clasifica o usa objetos según contexto.","evidencia":"observación directa y diálogo con familias."},"literatura":{"tema":"canciones corporales, cuentos de higiene y secuencias de rutina.","competencia":"asocia palabra, gesto y acción.","avance":"anticipa partes de la rutina mediante imágenes, sonidos o palabras.","evidencia":"registro narrativo."},"arte":{"tema":"cuerpo, colores, figuras y marcas en distintos soportes.","competencia":"representa sensaciones y acciones con huellas, modelado o garabateo.","avance":"elige materiales y participa con intención.","evidencia":"portafolio artístico."}}'::jsonb, 3)
