insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-S1-P3', 'step-1', 3, 'Periodo III', 'S1.3', 'Descubro mis sentidos y mis movimientos', '{"alcance":"Potenciar la percepción sensorial, la coordinación fina y gruesa, el ritmo, el equilibrio y la expresión corporal mediante experiencias de arte, música, movimiento y exploración.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños reconocen su propio cuerpo, fortalecen vínculos positivos con adultos y pares, y ganan confianza para participar en experiencias de arte, música, ritmo y movimiento.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños expresan emociones, preferencias sensoriales, agrado, rechazo, curiosidad o disfrute mediante imitación, dramatización, canto, movimiento, gestos y experiencias estéticas.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños exploran texturas, sonidos, colores, olores, equilibrio, desplazamientos y materiales artísticos, descubriendo relaciones entre su cuerpo, los objetos y el espacio.","indagar":"Observar preferencias sensoriales, exploración de texturas, sonidos, colores, olores, equilibrio, desplazamientos, respuesta al ritmo, formas de disfrute y señales de sobrecarga o rechazo.","proyectar":"Diseñar ambientes motrices y artísticos con desafíos graduales, instrumentos simples, materiales variados, circuitos seguros, experiencias de imitación, apoyos corporales y alternativas sensoriales de participación.","vivir":"Propiciar experiencias de música, ritmo, rondas, dramatización, gateo, equilibrio, desplazamientos con objetos, pintura con manos, garabateo, modelado y exploración de materiales diversos.","valorar":"Interpretar disfrute, participación gradual, respuestas sensoriales, expresión corporal, coordinación y preferencias para ajustar intensidad de estímulos, materiales, apoyos y formas de participación.","juego":"Tema: juegos corporales, rondas, imitación y circuitos. Competencia: ajusta movimientos al ritmo y al espacio. Avance: gatea, camina, trepa o equilibra con mayor seguridad. Evidencia: video corto autorizado o registro fotográfico.","exploracion":"Tema: texturas, sonidos, colores, olores, equilibrio y desplazamientos. Competencia: compara sensaciones y comunica preferencias. Avance: participa con menor rechazo o con apoyos graduales. Evidencia: registro sensorial.","literatura":"Tema: cuentos rítmicos, onomatopeyas, canciones y juegos de repetición. Competencia: escucha, imita sonidos y anticipa secuencias. Avance: participa con gestos, palabras o movimientos. Evidencia: registro anecdótico o audio autorizado.","arte":"Tema: pintura con manos, garabateo, modelado, instrumentos y danza. Competencia: expresa emociones mediante color, sonido y movimiento. Avance: explora materiales diversos y sostiene la experiencia. Evidencia: portafolio artístico.","nucleos":"Texturas; sonidos; colores; olores; garabateo; dáctilopintura; ritmo; equilibrio; danza.","saberes":"Colores primarios; figuras simples; arriba/abajo; dentro/fuera; cerca/lejos; sonidos, ritmos y movimiento corporal.","competencias":"Participa en experiencias artísticas y motrices; explora materiales; comunica preferencias sensoriales; ajusta el cuerpo a movimientos guiados.","evidencias":"Fotografías de producciones; registro narrativo; video corto autorizado de movimiento; portafolio artístico.","dua":"Alternativas de textura; participación gradual; reducción de ruido; materiales adaptados; apoyo corporal seguro.","caribe":"Exploración de sonidos, ritmos, rondas, colores, olores, brisas y movimientos propios del entorno Caribe, incorporando música, oralidad familiar y expresión corporal como mediaciones culturales.","gire":"Controlar intensidad sonora, prevenir caídas en circuitos, ofrecer alternativas ante sobrecarga sensorial, usar materiales no tóxicos y acompañar movimientos de gateo, equilibrio, desplazamiento y exploración artística.","procesos":"Percepción sensorial; coordinación motriz fina y gruesa; expresión corporal y emocional; exploración de ritmo, música, textura y movimiento; tolerancia progresiva a materiales y estímulos.","ambientes":"Espacios amplios, ventilados, con circuitos seguros, materiales no tóxicos, texturas graduadas, control de ruido, hidratación, pausas de calma y alternativas de participación sensorial.","indicadores":"Manipula materiales; se mueve al ritmo; explora texturas, sonidos y colores; realiza garabatos o huellas; expresa agrado, rechazo o curiosidad; sostiene experiencias sensoriales con apoyo progresivo.","documentacion":"Portafolio artístico, registro sensorial, fotografías comentadas, video corto autorizado y notas de observación. Alertas: rechazo intenso y persistente a múltiples estímulos, caídas frecuentes sin progreso, ausencia de exploración motriz, irritabilidad sensorial sostenida; dialogar con familia y revisar apoyos.","emocional":"Disfrute, calma, expresión corporal de emociones y preferencias sensoriales.","familia":"Compartir canciones familiares, juegos de movimiento o fotos de exploración corporal en casa.","observacion":"Se observa cómo las niñas y los niños manipulan materiales, se mueven al ritmo, exploran texturas, realizan garabatos, expresan agrado o rechazo y sostienen la experiencia con apoyo. Estas evidencias permiten valorar avances en percepción sensorial, coordinación motriz, expresión corporal y disfrute estético. A partir de lo observado, se ajustan intensidad de estímulos, materiales, tiempos y formas de participación."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños reconocen su propio cuerpo, fortalecen vínculos positivos con adultos y pares, y ganan confianza para participar en experiencias de arte, música, ritmo y movimiento."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños expresan emociones, preferencias sensoriales, agrado, rechazo, curiosidad o disfrute mediante imitación, dramatización, canto, movimiento, gestos y experiencias estéticas."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños exploran texturas, sonidos, colores, olores, equilibrio, desplazamientos y materiales artísticos, descubriendo relaciones entre su cuerpo, los objetos y el espacio."}]'::jsonb, '{"juego":{"tema":"juegos corporales, rondas, imitación y circuitos.","competencia":"ajusta movimientos al ritmo y al espacio.","avance":"gatea, camina, trepa o equilibra con mayor seguridad.","evidencia":"video corto autorizado o registro fotográfico."},"exploracion":{"tema":"texturas, sonidos, colores, olores, equilibrio y desplazamientos.","competencia":"compara sensaciones y comunica preferencias.","avance":"participa con menor rechazo o con apoyos graduales.","evidencia":"registro sensorial."},"literatura":{"tema":"cuentos rítmicos, onomatopeyas, canciones y juegos de repetición.","competencia":"escucha, imita sonidos y anticipa secuencias.","avance":"participa con gestos, palabras o movimientos.","evidencia":"registro anecdótico o audio autorizado."},"arte":{"tema":"pintura con manos, garabateo, modelado, instrumentos y danza.","competencia":"expresa emociones mediante color, sonido y movimiento.","avance":"explora materiales diversos y sostiene la experiencia.","evidencia":"portafolio artístico."}}'::jsonb, 4)
