insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-S1-P4', 'step-1', 4, 'Periodo IV', 'S1.4', 'Juego, clasifico y entiendo mi entorno', '{"alcance":"Promover la organización, agrupación, clasificación y representación de elementos del entorno mediante juego, manipulación de material concreto y experiencias numéricas iniciales.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños se reconocen como exploradores curiosos, participan con otros en juegos de agrupación, ordenamiento y clasificación espontánea, y comparten hallazgos con adultos y pares.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños expresan preferencias, señalan atributos como color, forma o tamaño, participan en canciones numéricas y comunican descubrimientos mediante gestos, palabras, marcas, huellas o acciones.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños disfrutan experiencias lúdicas de clasificación, seriación inicial, conteo 1–5, manipulación de material concreto, encajes, agrupaciones y exploración de objetos del entorno.","indagar":"Observar objetos de interés, clasificaciones espontáneas, formas de señalar atributos, participación en canciones numéricas, manipulación de bloques, fichas, tapas, encajes y materiales concretos.","proyectar":"Diseñar ambientes y materiales para agrupar por color, forma o tamaño, incorporar encajes, rompecabezas sencillos, conteo en rutinas, canciones numéricas, experiencias sensoriales y opciones de respuesta verbal o no verbal.","vivir":"Propiciar juegos con bloques, tapas, fichas, juguetes y encajes, conteo en rutinas, agrupación, comparación, organización, canciones numéricas y representación mediante huellas, marcas espontáneas y producciones libres.","valorar":"Interpretar formas de organizar objetos, lenguaje usado, participación en conteo, agrupaciones, señales de comparación y evidencias de juego para proyectar nuevas experiencias de clasificación y conteo cotidiano.","juego":"Tema: bloques, tapas, fichas, encajes, canciones numéricas y juego de agrupación. Competencia: manipula, agrupa, compara y comparte hallazgos. Avance: organiza objetos por atributos con apoyo o espontáneamente. Evidencia: fotografías de juego.","exploracion":"Tema: objetos cotidianos, color, forma, tamaño, conteo oral 1–5 y nociones dentro/fuera. Competencia: observa atributos y relaciones. Avance: señala, toma, entrega o clasifica. Evidencia: secuencia de manipulación y registro anecdótico.","literatura":"Tema: cuentos breves, rimas y canciones con números, objetos, cuerpo y entorno. Competencia: atiende, repite, señala o anticipa. Avance: participa en juegos orales y canciones numéricas. Evidencia: observación de respuesta verbal/no verbal.","arte":"Tema: huellas, marcas espontáneas, primeros trazos con nombre, figuras y composición libre. Competencia: representa mediante acción, color y marca. Avance: produce trazos o agrupaciones visuales. Evidencia: portafolio sensorial y producción libre.","nucleos":"Dentro/fuera; arriba/abajo; grande/pequeño; colores; agrupaciones simples; conteo oral en canciones.","saberes":"Colores primarios; círculo, cuadrado, triángulo familiarizados; conteo oral 1–5; correspondencia inicial; cinco sentidos; encajes; primeros trazos con nombre.","competencias":"Agrupa, compara y manipula objetos; participa en juegos de clasificación; usa comunicación verbal o no verbal; relaciona cantidades con experiencias reales.","evidencias":"Fotografías de agrupaciones; registro anecdótico; producciones libres; observación de juego.","dua":"Material concreto; objetos grandes; modelamiento; consignas breves; elección entre dos opciones.","caribe":"Uso de objetos cotidianos del hogar y del entorno barranquillero: tapas, frutas, recipientes, juguetes, prendas, colores, sonidos y materiales familiares para agrupar, comparar y jugar.","gire":"Cuidar el uso de piezas pequeñas, mantener materiales organizados, evitar objetos cortantes o riesgosos, prevenir tropiezos, guardar después de usar y seguir instrucciones breves con apoyo del adulto.","procesos":"Agrupación y clasificación inicial; manipulación de material concreto; comunicación de atributos; conteo oral en canciones y rutinas; representación mediante huellas, marcas, encajes y producciones libres.","ambientes":"Material concreto grande y seguro, superficies limpias, canastas organizadas, consignas breves, hidratación, pausas activas, espacios para manipular sin sobrecarga y acompañamiento cercano.","indicadores":"Agrupa objetos por color, forma, tamaño o función con apoyo; participa en canciones numéricas; señala atributos; compara objetos; entrega, toma o guarda materiales; representa con huellas o marcas espontáneas.","documentacion":"Fotografías de agrupaciones, registro anecdótico, producciones libres y observación de juego. Alertas: dificultad persistente para manipular objetos, baja respuesta a instrucciones simples, ausencia de interacción con materiales o pares, frustración intensa ante cambios; ajustar apoyos y conversar con familia.","emocional":"Tolerancia inicial a turnos breves; cooperación simple; disfrute compartido.","familia":"Clasificar juguetes, ropa o frutas en casa; cantar canciones numéricas; enviar evidencias de juego.","observacion":"Se observa cómo las niñas y los niños exploran, manipulan, agrupan, señalan atributos, participan en canciones numéricas y comparten hallazgos con el adulto mediante gestos, palabras o acciones. Estas evidencias permiten valorar avances en exploración del medio, comunicación emergente, organización inicial del pensamiento y participación en juego. A partir de lo observado, se ajustan materiales, consignas, apoyos o nuevas experiencias de clasificación y conteo cotidiano."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños se reconocen como exploradores curiosos, participan con otros en juegos de agrupación, ordenamiento y clasificación espontánea, y comparten hallazgos con adultos y pares."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños expresan preferencias, señalan atributos como color, forma o tamaño, participan en canciones numéricas y comunican descubrimientos mediante gestos, palabras, marcas, huellas o acciones."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños disfrutan experiencias lúdicas de clasificación, seriación inicial, conteo 1–5, manipulación de material concreto, encajes, agrupaciones y exploración de objetos del entorno."}]'::jsonb, '{"juego":{"tema":"bloques, tapas, fichas, encajes, canciones numéricas y juego de agrupación.","competencia":"manipula, agrupa, compara y comparte hallazgos.","avance":"organiza objetos por atributos con apoyo o espontáneamente.","evidencia":"fotografías de juego."},"exploracion":{"tema":"objetos cotidianos, color, forma, tamaño, conteo oral 1–5 y nociones dentro/fuera.","competencia":"observa atributos y relaciones.","avance":"señala, toma, entrega o clasifica.","evidencia":"secuencia de manipulación y registro anecdótico."},"literatura":{"tema":"cuentos breves, rimas y canciones con números, objetos, cuerpo y entorno.","competencia":"atiende, repite, señala o anticipa.","avance":"participa en juegos orales y canciones numéricas.","evidencia":"observación de respuesta verbal/no verbal."},"arte":{"tema":"huellas, marcas espontáneas, primeros trazos con nombre, figuras y composición libre.","competencia":"representa mediante acción, color y marca.","avance":"produce trazos o agrupaciones visuales.","evidencia":"portafolio sensorial y producción libre."}}'::jsonb, 5)
on conflict (version_id, id) do update set level_id = excluded.level_id, period = excluded.period, period_label = excluded.period_label,
  period_code = excluded.period_code, title = excluded.title, fields = excluded.fields, purposes = excluded.purposes,
