insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-S2-P1', 'step-2', 1, 'Periodo I', 'S2.1', 'Mi cuerpo explora, nombra y compara', '{"alcance":"Ampliar el reconocimiento del cuerpo y del entorno mediante experiencias sensoriales, motrices y cognitivas que fortalezcan el lenguaje para nombrar, comparar, clasificar y contar en situaciones cotidianas.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños se identifican como exploradores activos de su cuerpo y ambiente, fortalecen vínculos seguros y participan en juegos donde reconocen sus capacidades, límites y posibilidades corporales.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños usan palabras, frases breves, gestos o señalamientos para nombrar partes del cuerpo, colores, figuras, cantidades, características, necesidades y emociones.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños participan en experiencias lúdicas de clasificación, conteo hasta cinco, comparación, exploración sensoperceptiva y reconocimiento de atributos en objetos cotidianos.","indagar":"Observar cómo nombran partes del cuerpo, colores, figuras, cantidades y objetos, cómo comparan, clasifican, siguen consignas simples y expresan necesidades durante el juego.","proyectar":"Diseñar rincones sensoriales y motrices con colores, figuras, conteo con objetos significativos, láminas, canciones, apoyos visuales, consignas breves, preguntas sencillas y material concreto.","vivir":"Propiciar juegos de clasificación por color, forma y tamaño, conteo en rutinas, circuitos sensoriales, conversaciones con láminas y objetos, y representación de sensaciones mediante trazos, colores y texturas.","valorar":"Interpretar avances en lenguaje, clasificación, conteo, exploración sensorial y participación motriz para ajustar consignas, materiales concretos, apoyos gestuales y oportunidades de expresión.","juego":"Tema: juegos de cuerpo, clasificación, color, forma, tamaño y conteo. Competencia: nombra, compara y agrupa objetos. Avance: sigue consignas simples y participa en conteo con material concreto. Evidencia: fotografías de clasificación.","exploracion":"Tema: cinco sentidos, posiciones, cantidades pequeñas y atributos de objetos. Competencia: explora, compara y describe. Avance: usa palabras o gestos para diferenciar características. Evidencia: registro narrativo y observación directa.","literatura":"Tema: láminas, cuentos cortos, canciones de cuerpo, colores y cantidades. Competencia: escucha, responde y amplía vocabulario. Avance: nombra objetos, colores o partes del cuerpo. Evidencia: audio autorizado o nota docente.","arte":"Tema: color, forma, textura, trazos y producciones con materiales variados. Competencia: representa sensaciones y atributos. Avance: elige materiales y comunica preferencias. Evidencia: portafolio y producción individual.","nucleos":"Cuerpo; colores; formas; tamaños; posiciones; cantidades pequeñas; cinco sentidos.","saberes":"Colores primarios/secundarios iniciales; figuras básicas; conteo 1–5; grande/pequeño; dentro/fuera; arriba/abajo; texturas, sonidos y olores.","competencias":"Nombra y compara objetos; clasifica por atributo; participa en conteo con material concreto; expresa necesidades.","evidencias":"Registro narrativo; fotografías de clasificación; audio autorizado de expresión oral; portafolio.","dua":"Secuencia visual; objetos concretos; apoyo gestual; una consigna a la vez; alternativas no verbales.","caribe":"Exploración de cuerpo, colores, formas, frutas, objetos familiares, sonidos, clima y espacios cotidianos de Barranquilla como base para nombrar, comparar, clasificar y contar.","gire":"Garantizar seguridad en circuitos sensoriales y motrices, hidratación, sombra, materiales grandes y limpios, seguimiento de consignas simples y acompañamiento en desplazamientos y manipulación de objetos.","procesos":"Reconocimiento corporal; ampliación de vocabulario; clasificación por atributos; conteo con material concreto; comparación de objetos; exploración sensoperceptiva.","ambientes":"Rincones ventilados, material concreto seguro, circuitos motrices con supervisión, agua disponible, sombra, pausas sensoriales, objetos higienizados y consignas visuales.","indicadores":"Nombra partes del cuerpo, colores u objetos; clasifica por color, forma o tamaño; participa en conteo 1–5 con apoyo; compara grande/pequeño; sigue una consigna simple; expresa necesidades.","documentacion":"Fotografías de clasificación, registro narrativo, audio autorizado y portafolio. Alertas: ausencia persistente de respuesta comunicativa, dificultad marcada para seguir consignas simples, poca exploración corporal o sensorial, irritabilidad sostenida; revisar mediaciones y dialogar con familia.","emocional":"Identificación de emociones básicas; pedir ayuda; tolerancia a turnos breves.","familia":"Juegos de clasificación con ropa, frutas o juguetes; registros breves de conteo cotidiano.","observacion":"Se observa cómo las niñas y los niños nombran, comparan, clasifican, siguen consignas simples y participan en conteo con material concreto. Estas evidencias permiten valorar avances en lenguaje, reconocimiento corporal, exploración sensoperceptiva, clasificación y uso de nociones en situaciones de juego. A partir de lo observado, se ajustan consignas, apoyos gestuales, materiales concretos y oportunidades de expresión verbal o no verbal."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños se identifican como exploradores activos de su cuerpo y ambiente, fortalecen vínculos seguros y participan en juegos donde reconocen sus capacidades, límites y posibilidades corporales."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños usan palabras, frases breves, gestos o señalamientos para nombrar partes del cuerpo, colores, figuras, cantidades, características, necesidades y emociones."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños participan en experiencias lúdicas de clasificación, conteo hasta cinco, comparación, exploración sensoperceptiva y reconocimiento de atributos en objetos cotidianos."}]'::jsonb, '{"juego":{"tema":"juegos de cuerpo, clasificación, color, forma, tamaño y conteo.","competencia":"nombra, compara y agrupa objetos.","avance":"sigue consignas simples y participa en conteo con material concreto.","evidencia":"fotografías de clasificación."},"exploracion":{"tema":"cinco sentidos, posiciones, cantidades pequeñas y atributos de objetos.","competencia":"explora, compara y describe.","avance":"usa palabras o gestos para diferenciar características.","evidencia":"registro narrativo y observación directa."},"literatura":{"tema":"láminas, cuentos cortos, canciones de cuerpo, colores y cantidades.","competencia":"escucha, responde y amplía vocabulario.","avance":"nombra objetos, colores o partes del cuerpo.","evidencia":"audio autorizado o nota docente."},"arte":{"tema":"color, forma, textura, trazos y producciones con materiales variados.","competencia":"representa sensaciones y atributos.","avance":"elige materiales y comunica preferencias.","evidencia":"portafolio y producción individual."}}'::jsonb, 6)
