insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-S2-P2', 'step-2', 2, 'Periodo II', 'S2.2', 'Mi cuerpo se organiza y se comunica con el entorno', '{"alcance":"Fortalecer la autonomía en rutinas de cuidado personal y organización del espacio, promoviendo lenguaje oral, secuencias de acción, clasificación funcional de objetos y participación en la vida cotidiana del aula.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños se reconocen capaces de participar en el cuidado de sí mismos, de sus objetos y del entorno, fortaleciendo autonomía, seguridad y pertenencia al grupo.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños comunican necesidades, emociones, preferencias, acuerdos y acciones durante rutinas de aseo, alimentación, juego, organización y vida práctica.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños aprenden mediante juego simbólico, clasificación de objetos, secuencias, uso funcional de materiales y exploración de rutinas cotidianas.","indagar":"Observar participación en aseo, alimentación, orden, cuidado del espacio, uso funcional de objetos, reconocimiento de normas y comunicación de necesidades o preferencias.","proyectar":"Diseñar ambientes de cuidado y organización con pictogramas de rutinas, juegos simbólicos, objetos clasificados por uso o lugar, secuencias primero-después-final y apoyos de anticipación.","vivir":"Propiciar juegos de imitación de aseo, alimentación y organización, clasificación por función o lugar, acciones de trasvasar, exprimir, enroscar, desenroscar y guardar, y dramatización de rutinas cotidianas.","valorar":"Interpretar autonomía en rutinas, lenguaje funcional, cooperación, secuencias de acción y cuidado del ambiente para ajustar pictogramas, anticipaciones, responsabilidades y mediaciones de vida práctica.","juego":"Tema: juego simbólico de aseo, alimentación, orden y cuidado. Competencia: imita rutinas, usa objetos funcionalmente y coopera. Avance: realiza secuencias de uno o dos pasos. Evidencia: fotografías de vida práctica.","exploracion":"Tema: funciones de objetos, clasificación por uso/lugar, abrir/cerrar, trasvasar y exprimir. Competencia: explora relaciones de causa, función y secuencia. Avance: organiza materiales con menor apoyo. Evidencia: lista descriptiva y observación.","literatura":"Tema: cuentos de rutinas, pictogramas, relatos de cuidado y canciones de transición. Competencia: comprende secuencias primero-después-final. Avance: anticipa rutinas y comunica necesidades. Evidencia: registro de conversación.","arte":"Tema: representación de rutinas con dibujo, modelado, collage o dramatización. Competencia: expresa acciones cotidianas con lenguajes artísticos. Avance: produce marcas o escenas simples con intención. Evidencia: producción y fotografía comentada.","nucleos":"Rutinas visuales; aseo; alimentación; guardar; abrir/cerrar; doblar; limpiar; pedir ayuda.","saberes":"Funciones de objetos; secuencias de uno o dos pasos; cuidado de materiales; cortesía; hábitos de higiene; clasificación por uso/lugar.","competencias":"Participa en rutinas con mayor autonomía; comunica necesidades; organiza materiales; coopera.","evidencias":"Lista de cotejo descriptiva; fotografías de vida práctica; diálogo con familias.","dua":"Pictogramas; modelamiento; anticipación; instrucciones fragmentadas; elección limitada.","caribe":"Rutinas de vida práctica conectadas con el contexto local: hidratación, lavado de manos, cuidado de ropa, organización de pertenencias, uso responsable del agua y cuidado del aula en clima cálido.","gire":"Reconocer objetos seguros, pedir ayuda, anticipar transiciones, mantener espacios despejados, seguir secuencias primero-después-final y cuidar materiales de higiene, alimentación y organización.","procesos":"Autonomía en rutinas; organización del espacio; comunicación funcional; secuencias de uno o dos pasos; uso y clasificación de objetos según función; cooperación inicial.","ambientes":"Ambiente de vida práctica con pictogramas, objetos reales seguros, zonas de aseo acompañadas, ventilación, hidratación, mobiliario a la altura de niñas y niños y tiempos flexibles.","indicadores":"Guarda materiales; sigue secuencias simples; pide ayuda; usa palabras de cortesía; reconoce para qué sirven objetos de cuidado; participa en alimentación, aseo y organización con menor apoyo.","documentacion":"Lista descriptiva, fotografías de vida práctica, diálogo con familias y observador individual. Alertas: pérdida de autonomía ya lograda, dificultad persistente para participar en rutinas, señales de cansancio, hambre, sueño o malestar no comunicadas; activar seguimiento familia-escuela.","emocional":"Autonomía; autocuidado; respeto de límites; cooperación en rutinas.","familia":"Reforzar guardar juguetes, doblar ropa sencilla, lavar manos y comunicar necesidades.","observacion":"Se observa cómo las niñas y los niños siguen secuencias de uno o dos pasos, guardan materiales, piden ayuda, usan palabras de cortesía y participan en rutinas de cuidado. Estas evidencias permiten valorar avances en autonomía, comunicación funcional, organización del espacio y cooperación. A partir de lo observado, se ajustan pictogramas, anticipaciones, modelamientos, tiempos y responsabilidades cotidianas."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños se reconocen capaces de participar en el cuidado de sí mismos, de sus objetos y del entorno, fortaleciendo autonomía, seguridad y pertenencia al grupo."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños comunican necesidades, emociones, preferencias, acuerdos y acciones durante rutinas de aseo, alimentación, juego, organización y vida práctica."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños aprenden mediante juego simbólico, clasificación de objetos, secuencias, uso funcional de materiales y exploración de rutinas cotidianas."}]'::jsonb, '{"juego":{"tema":"juego simbólico de aseo, alimentación, orden y cuidado.","competencia":"imita rutinas, usa objetos funcionalmente y coopera.","avance":"realiza secuencias de uno o dos pasos.","evidencia":"fotografías de vida práctica."},"exploracion":{"tema":"funciones de objetos, clasificación por uso/lugar, abrir/cerrar, trasvasar y exprimir.","competencia":"explora relaciones de causa, función y secuencia.","avance":"organiza materiales con menor apoyo.","evidencia":"lista descriptiva y observación."},"literatura":{"tema":"cuentos de rutinas, pictogramas, relatos de cuidado y canciones de transición.","competencia":"comprende secuencias primero-después-final.","avance":"anticipa rutinas y comunica necesidades.","evidencia":"registro de conversación."},"arte":{"tema":"representación de rutinas con dibujo, modelado, collage o dramatización.","competencia":"expresa acciones cotidianas con lenguajes artísticos.","avance":"produce marcas o escenas simples con intención.","evidencia":"producción y fotografía comentada."}}'::jsonb, 7)
