insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-S2-P3', 'step-2', 3, 'Periodo III', 'S2.3', 'Mis palabras cuentan lo que vivo', '{"alcance":"Potenciar el lenguaje oral expresivo y comprensivo, la atención, la memoria y la representación de experiencias mediante cuentos, juegos simbólicos, música, movimiento y relatos cotidianos.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños se reconocen como narradores de su propia experiencia, comparten lo que sienten, piensan y viven, y encuentran en el grupo un espacio seguro para ser escuchados.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños usan frases más completas, preguntas, respuestas, gestos, dramatizaciones, canciones, rimas y juegos de lenguaje para comunicar ideas, emociones y experiencias.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños disfrutan cuentos, imágenes, títeres, rondas, dramatizaciones y juegos simbólicos que les permiten comprender secuencias, personajes, acciones y situaciones de su vida cotidiana.","indagar":"Observar longitud y claridad de frases, respuesta a preguntas sencillas, interés por cuentos, atención, escucha, turnos de palabra y lenguaje espontáneo en juego simbólico.","proyectar":"Diseñar ambientes de lenguaje con lectura de imágenes, cuentos breves, juegos de preguntas, títeres, máscaras, rimas, canciones, sonidos, objetos significativos y alternativas de respuesta oral, gestual o gráfica.","vivir":"Propiciar lectura de cuentos con apoyo visual, juegos para completar frases, reconocimiento de personajes, dramatización de escenas, rimas, canciones, títeres, narración de experiencias propias y dibujos narrados.","valorar":"Interpretar avances en oralidad, comprensión, memoria, turnos, vocabulario y expresión emocional vinculada a relatos para ajustar preguntas, cuentos, objetos narrativos y apoyos visuales.","juego":"Tema: títeres, máscaras, juego simbólico, dramatización y rondas. Competencia: representa personajes, acciones y emociones. Avance: participa en relatos dramatizados y turnos de palabra. Evidencia: fotografía de dramatización.","exploracion":"Tema: objetos significativos, experiencias vividas y situaciones del aula. Competencia: relaciona objetos con relatos y emociones. Avance: describe lo que ve o vive. Evidencia: objeto narrado y registro docente.","literatura":"Tema: cuentos, imágenes, rimas, canciones, onomatopeyas y preguntas qué/quién/dónde. Competencia: escucha, anticipa, responde y narra. Avance: completa frases o nombra personajes. Evidencia: audio autorizado o dibujo narrado.","arte":"Tema: dibujo narrado, música, movimiento, teatro y creación de personajes. Competencia: expresa historias con cuerpo, voz y materiales. Avance: representa una escena o emoción. Evidencia: producción o registro audiovisual autorizado.","nucleos":"Cuentos; imágenes; títeres; rimas; canciones; onomatopeyas; relatos cotidianos.","saberes":"Personajes; secuencias; preguntas qué/quién/dónde; vocabulario de experiencias; sonidos, rimas y expresión emocional.","competencias":"Usa frases breves; describe imágenes; responde preguntas; participa en juegos de lenguaje.","evidencias":"Audio autorizado; registro narrativo; dibujo narrado; fotografía de dramatización.","dua":"Títeres; láminas; objetos reales; preguntas cerradas o de elección; dictado al adulto.","caribe":"Oralidad Caribe, rondas, canciones familiares, cuentos breves, relatos del hogar, sonidos del barrio y experiencias cotidianas como fuente de lenguaje, pertenencia y narración.","gire":"Generar círculos seguros de palabra, respetar turnos, cuidar la voz, reconocer adultos de apoyo, ofrecer alternativas de expresión y atender señales de frustración, silencio persistente o dificultad para comunicar.","procesos":"Lenguaje oral expresivo y comprensivo; escucha; memoria; turnos de palabra; narración de experiencias; representación mediante cuentos, títeres, canciones y dibujo narrado.","ambientes":"Espacios tranquilos de lectura, asamblea breve, rincones con libros resistentes, títeres, láminas, música moderada, ventilación y posibilidad de responder con gesto, palabra, dibujo o movimiento.","indicadores":"Completa frases; nombra personajes; anticipa situaciones; canta o rima con apoyo; responde preguntas qué/quién/dónde; narra experiencias breves; participa en dramatizaciones.","documentacion":"Audio autorizado, dibujo narrado, registro anecdótico, fotografía de dramatización y cuaderno viajero. Alertas: escasa respuesta a sonidos o voces, ausencia persistente de intención comunicativa, frustración intensa al expresarse, dificultades de interacción; conversar con familia y activar apoyos.","emocional":"Expresar emociones en cuentos; escuchar al otro; respetar turnos de palabra.","familia":"Leer cuentos cortos; enviar audios del niño contando algo o cantando; compartir libro favorito.","observacion":"Se observa cómo las niñas y los niños completan frases, nombran personajes, anticipan situaciones, cantan, riman, dramatizan o narran experiencias con apoyo. Estas evidencias permiten valorar avances en oralidad, comprensión, memoria, escucha, expresión emocional y participación en literatura. A partir de lo observado, se ajustan preguntas, apoyos visuales, cuentos, objetos narrativos y oportunidades de conversación."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños se reconocen como narradores de su propia experiencia, comparten lo que sienten, piensan y viven, y encuentran en el grupo un espacio seguro para ser escuchados."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños usan frases más completas, preguntas, respuestas, gestos, dramatizaciones, canciones, rimas y juegos de lenguaje para comunicar ideas, emociones y experiencias."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños disfrutan cuentos, imágenes, títeres, rondas, dramatizaciones y juegos simbólicos que les permiten comprender secuencias, personajes, acciones y situaciones de su vida cotidiana."}]'::jsonb, '{"juego":{"tema":"títeres, máscaras, juego simbólico, dramatización y rondas.","competencia":"representa personajes, acciones y emociones.","avance":"participa en relatos dramatizados y turnos de palabra.","evidencia":"fotografía de dramatización."},"exploracion":{"tema":"objetos significativos, experiencias vividas y situaciones del aula.","competencia":"relaciona objetos con relatos y emociones.","avance":"describe lo que ve o vive.","evidencia":"objeto narrado y registro docente."},"literatura":{"tema":"cuentos, imágenes, rimas, canciones, onomatopeyas y preguntas qué/quién/dónde.","competencia":"escucha, anticipa, responde y narra.","avance":"completa frases o nombra personajes.","evidencia":"audio autorizado o dibujo narrado."},"arte":{"tema":"dibujo narrado, música, movimiento, teatro y creación de personajes.","competencia":"expresa historias con cuerpo, voz y materiales.","avance":"representa una escena o emoción.","evidencia":"producción o registro audiovisual autorizado."}}'::jsonb, 8)
