insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-S2-P4', 'step-2', 4, 'Periodo IV', 'S2.4', 'Juego, organizo y resuelvo pequeños retos', '{"alcance":"Integrar habilidades motrices, cognitivas, comunicativas y socioemocionales en juegos, mini-proyectos y retos cotidianos donde las niñas y los niños clasifiquen, organicen, cuenten, narren, cooperen y resuelvan problemas simples.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños se reconocen como miembros activos del grupo, capaces de aportar, cooperar, participar en acuerdos y sentirse competentes en pequeños proyectos colectivos.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños explican procedimientos con sus palabras, negocian acuerdos simples, comparten resultados, expresan emociones ante los retos y representan soluciones mediante juego, cuerpo, palabra o producción gráfica.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños integran juego, exploración, arte y resolución de problemas para clasificar, organizar, contar, narrar, construir y cooperar en situaciones significativas.","indagar":"Observar autonomía, iniciativa, cooperación, estrategias para clasificar, contar, organizar materiales, resolver pequeños conflictos y participar en retos o mini-proyectos.","proyectar":"Diseñar mini-proyectos de organización, juego y construcción con materiales de clasificación, conteo aplicado, rompecabezas, recorte, roles concretos, apoyos visuales y mediaciones para el trabajo cooperativo.","vivir":"Propiciar experiencias de clasificación con dos criterios iniciales, reparto de materiales, conteo aplicado, rompecabezas, recorte de líneas simples, construcción, organización de espacios y socialización de lo realizado.","valorar":"Interpretar estrategias, cooperación, turnos, intentos de solución y participación en mini-proyectos para ajustar roles, materiales, tiempos, mediaciones de convivencia y complejidad de retos.","juego":"Tema: mini-proyectos, ludoteca, tienda de juguetes, rompecabezas y retos cooperativos. Competencia: organiza, cuenta, reparte y acuerda turnos. Avance: intenta soluciones y coopera. Evidencia: registro de proyecto.","exploracion":"Tema: clasificación con criterios, conteo aplicado, secuencias, recorte y construcción. Competencia: usa ensayo-error para resolver retos cotidianos. Avance: organiza materiales por función, forma, color o tamaño. Evidencia: fotografías de retos.","literatura":"Tema: instrucciones breves, relatos de lo construido, canciones y cuentos de cooperación. Competencia: escucha consignas, explica procedimientos y narra resultados. Avance: comunica qué hizo y cómo lo hizo. Evidencia: conversación docente-niño.","arte":"Tema: producciones gráfico-plásticas intencionadas, recorte, collage y construcción. Competencia: transforma materiales para resolver un proyecto. Avance: usa herramientas con apoyo y propósito. Evidencia: producción y portafolio.","nucleos":"Clasificación avanzada inicial; conteo aplicado; recorte; rompecabezas; cooperación; turnos.","saberes":"Color/tamaño/forma/función; conteo aplicado; coordinación fina y gruesa; secuencia de acciones; acuerdos de juego.","competencias":"Resuelve situaciones simples; usa ensayo-error; participa en juegos con normas; coopera con pares.","evidencias":"Registro de proyecto; fotografías de retos; producciones; observación directa.","dua":"Roles concretos; material manipulativo; apoyos visuales; tiempo flexible; mediación en turnos.","caribe":"Mini-proyectos con objetos del hogar, juguetes, frutas, materiales reciclables, tienda simbólica y organización de espacios cotidianos del aula y la familia.","gire":"Usar con seguridad tijeras adaptadas, piezas, cajas y objetos de construcción; organizar espacios de trabajo; cuidar turnos; prevenir conflictos por materiales y acompañar la resolución de pequeños retos.","procesos":"Resolución de pequeños retos; clasificación con criterios iniciales; conteo aplicado; cooperación; espera de turnos; organización de materiales; ensayo-error.","ambientes":"Ambientes de proyecto con roles claros, materiales manipulativos seguros, mesas despejadas, pausas activas, hidratación, mediación de conflictos y zonas para construir, clasificar y guardar.","indicadores":"Cuenta y reparte objetos; organiza materiales; intenta soluciones; coopera con pares; espera turnos breves; participa en mini-proyectos; comunica qué hizo con apoyo verbal o gestual.","documentacion":"Registro de proyecto, fotografías de retos, producciones y observación directa. Alertas: frustración persistente ante retos simples, dificultad marcada para compartir materiales, bajo interés en interacción o juego, conductas de riesgo con objetos; ajustar apoyos y dialogar con familia.","emocional":"Cooperación; tolerancia a la frustración; reparación; acuerdos simples.","familia":"Organizar un rincón de juguetes en casa; contar objetos cotidianos; compartir evidencia breve.","observacion":"Se observa cómo las niñas y los niños cuentan, reparten, esperan turnos breves, intentan soluciones, cooperan y participan en mini-proyectos. Estas evidencias permiten valorar avances en resolución de problemas simples, clasificación, conteo aplicado, comunicación de procedimientos y convivencia. A partir de lo observado, se ajustan roles, materiales, tiempos, apoyos para turnos y retos de mayor o menor complejidad."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños se reconocen como miembros activos del grupo, capaces de aportar, cooperar, participar en acuerdos y sentirse competentes en pequeños proyectos colectivos."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños explican procedimientos con sus palabras, negocian acuerdos simples, comparten resultados, expresan emociones ante los retos y representan soluciones mediante juego, cuerpo, palabra o producción gráfica."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños integran juego, exploración, arte y resolución de problemas para clasificar, organizar, contar, narrar, construir y cooperar en situaciones significativas."}]'::jsonb, '{"juego":{"tema":"mini-proyectos, ludoteca, tienda de juguetes, rompecabezas y retos cooperativos.","competencia":"organiza, cuenta, reparte y acuerda turnos.","avance":"intenta soluciones y coopera.","evidencia":"registro de proyecto."},"exploracion":{"tema":"clasificación con criterios, conteo aplicado, secuencias, recorte y construcción.","competencia":"usa ensayo-error para resolver retos cotidianos.","avance":"organiza materiales por función, forma, color o tamaño.","evidencia":"fotografías de retos."},"literatura":{"tema":"instrucciones breves, relatos de lo construido, canciones y cuentos de cooperación.","competencia":"escucha consignas, explica procedimientos y narra resultados.","avance":"comunica qué hizo y cómo lo hizo.","evidencia":"conversación docente-niño."},"arte":{"tema":"producciones gráfico-plásticas intencionadas, recorte, collage y construcción.","competencia":"transforma materiales para resolver un proyecto.","avance":"usa herramientas con apoyo y propósito.","evidencia":"producción y portafolio."}}'::jsonb, 9)
