insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-S3-P1', 'step-3', 1, 'Periodo I', 'S3.1', 'Mis manos crean, mi cuerpo se prepara', '{"alcance":"Fortalecer coordinación motriz fina y gruesa, lateralidad, esquema corporal, vida práctica y preparación grafomotriz mediante experiencias lúdicas, corporales, sensoriales y creativas.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños construyen una identidad de “yo puedo” en relación con otros, ganan autonomía en rutinas, enfrentan retos corporales y se sienten valorados por sus avances.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños nombran partes del cuerpo, acciones, preferencias y necesidades, y representan lo que viven mediante movimiento, trazos, modelado, juego corporal y creación manual.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños disfrutan experiencias de movimiento, manipulación, vida práctica, coordinación motriz, lateralidad, esquema corporal y creación para comprender su cuerpo como medio de acción y conocimiento.","indagar":"Observar agarre, presión, coordinación ojo-mano, uso de tijera, rasgado, equilibrio, saltos, rutinas, lateralidad espontánea, seguridad corporal y uso de herramientas.","proyectar":"Diseñar ambientes de vida práctica y grafomotricidad con estaciones de trabajo, superficies verticales, herramientas graduadas, circuitos motrices, pinza, ensartado, modelado y apoyos corporales seguros.","vivir":"Propiciar experiencias de vida práctica, trasvasar, exprimir, abotonar, doblar, limpiar, trazar en arena, pintura, espuma y papel grande, recortar con guía, modelar, participar en circuitos y juegos de esquema corporal.","valorar":"Interpretar progresos motrices, autonomía, seguridad corporal, comunicación de acciones y perseverancia para ajustar herramientas, superficies, formatos, apoyos corporales o tiempos de exploración.","juego":"Tema: estaciones de vida práctica, circuitos, esquema corporal y juegos de lateralidad inicial. Competencia: coordina movimientos finos y gruesos. Avance: usa herramientas, participa en retos y cuida materiales. Evidencia: fotos de vida práctica.","exploracion":"Tema: cuerpo, espacio, derecha/izquierda incipiente, orientación y seguridad corporal. Competencia: explora movimientos, superficies y herramientas. Avance: ajusta fuerza, presión y desplazamiento. Evidencia: lista descriptiva y registro narrativo.","literatura":"Tema: cuentos corporales, instrucciones rimadas, canciones de movimiento y relatos de acciones. Competencia: comprende y verbaliza acciones corporales. Avance: nombra partes del cuerpo y secuencias. Evidencia: conversación o audio autorizado.","arte":"Tema: trazos rectos, curvos, ondas, circulares, modelado, pintura, espuma y papel grande. Competencia: representa movimiento y fortalece grafomotricidad. Avance: usa materiales con intención. Evidencia: producciones grafomotrices y portafolio.","nucleos":"Esquema corporal; lateralidad inicial; orientación espacial; pinza; grafomotricidad; seguridad corporal.","saberes":"Partes del cuerpo; derecha/izquierda incipiente; arriba/abajo; trazos rectos, curvos, ondas, circulares; ordenar, limpiar, trasvasar, abrir/cerrar; uso seguro de herramientas.","competencias":"Coordina movimientos finos y gruesos; usa herramientas con control progresivo; participa en rutinas de vida práctica; comunica acciones y necesidades.","evidencias":"Fotos de vida práctica; producciones grafomotrices; registros narrativos; lista de cotejo descriptiva; portafolio.","dua":"Trazos en gran formato; superficies verticales; herramientas gruesas; apoyo físico seguro; tiempos flexibles; alternativa táctil.","caribe":"Movimiento, vida práctica y grafomotricidad en relación con patios, rondas, juegos corporales, cuidado del cuerpo frente al calor, hidratación y exploración de espacios escolares.","gire":"Prevenir caídas en circuitos, usar herramientas graduadas con acompañamiento, mantener rutas despejadas, cuidar tijeras o punzones adaptados y reconocer límites corporales durante el movimiento.","procesos":"Coordinación motriz fina y gruesa; esquema corporal; lateralidad inicial; vida práctica; grafomotricidad lúdica; autonomía y seguridad corporal.","ambientes":"Ambientes con superficies verticales y horizontales, herramientas graduadas, circuitos seguros, agua disponible, sombra, tiempos de descanso, materiales no tóxicos y acompañamiento corporal respetuoso.","indicadores":"Usa herramientas con intención; realiza trazos lúdicos; participa en circuitos; cuida materiales; nombra partes del cuerpo; ajusta fuerza y presión; comunica acciones y necesidades.","documentacion":"Fotos de vida práctica, producciones grafomotrices, lista descriptiva, registro narrativo y portafolio. Alertas: dificultad persistente en agarre, equilibrio, coordinación o uso seguro de herramientas; cansancio excesivo, dolor referido o rechazo sostenido a movimiento; informar a familia y acompañar.","emocional":"Autonomía; confianza corporal; autorregulación con acompañamiento; perseverancia ante retos.","familia":"Doblar prenda simple, guardar juguetes por categorías, limpiar una superficie pequeña; enviar fotos y nota de qué fue fácil/difícil.","observacion":"Se observa cómo las niñas y los niños usan materiales con intención, realizan trazos lúdicos, participan en circuitos, cuidan herramientas, nombran partes del cuerpo y comunican acciones o necesidades. Estas evidencias permiten valorar avances en coordinación motriz, autonomía, seguridad corporal, grafomotricidad y vida práctica. A partir de lo observado, se ajustan herramientas, superficies, formatos, apoyos físicos o tiempos de exploración."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños construyen una identidad de “yo puedo” en relación con otros, ganan autonomía en rutinas, enfrentan retos corporales y se sienten valorados por sus avances."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños nombran partes del cuerpo, acciones, preferencias y necesidades, y representan lo que viven mediante movimiento, trazos, modelado, juego corporal y creación manual."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños disfrutan experiencias de movimiento, manipulación, vida práctica, coordinación motriz, lateralidad, esquema corporal y creación para comprender su cuerpo como medio de acción y conocimiento."}]'::jsonb, '{"juego":{"tema":"estaciones de vida práctica, circuitos, esquema corporal y juegos de lateralidad inicial.","competencia":"coordina movimientos finos y gruesos.","avance":"usa herramientas, participa en retos y cuida materiales.","evidencia":"fotos de vida práctica."},"exploracion":{"tema":"cuerpo, espacio, derecha/izquierda incipiente, orientación y seguridad corporal.","competencia":"explora movimientos, superficies y herramientas.","avance":"ajusta fuerza, presión y desplazamiento.","evidencia":"lista descriptiva y registro narrativo."},"literatura":{"tema":"cuentos corporales, instrucciones rimadas, canciones de movimiento y relatos de acciones.","competencia":"comprende y verbaliza acciones corporales.","avance":"nombra partes del cuerpo y secuencias.","evidencia":"conversación o audio autorizado."},"arte":{"tema":"trazos rectos, curvos, ondas, circulares, modelado, pintura, espuma y papel grande.","competencia":"representa movimiento y fortalece grafomotricidad.","avance":"usa materiales con intención.","evidencia":"producciones grafomotrices y portafolio."}}'::jsonb, 10)
