insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-S3-P2', 'step-3', 2, 'Periodo II', 'S3.2', 'Hablo, escucho y narro lo que vivo', '{"alcance":"Potenciar lenguaje oral expresivo y comprensivo, escucha, memoria, conciencia fonológica inicial y narración mediante cuentos, conversaciones, música, dramatización y juego simbólico.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños se reconocen como narradores de experiencias, ideas y emociones, participan en conversaciones del grupo y fortalecen vínculos al escuchar y ser escuchados.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños usan lenguaje verbal y no verbal para describir, preguntar, responder, secuenciar, dialogar, dramatizar, cantar, jugar con sonidos y representar historias.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños disfrutan literatura, dramatización, música, rimas, cuentos, conversaciones y juegos sonoros como formas de explorar el lenguaje y comprender su mundo social y cultural.","indagar":"Observar longitud de frase, claridad, pronunciación, comprensión de instrucciones, atención en cuentos, turnos conversacionales y lenguaje espontáneo en juego simbólico.","proyectar":"Diseñar ambientes de conversación y narración con lectura dialógica, secuencias de imágenes, rimas, adivinanzas, sonidos iniciales, onomatopeyas, praxias lúdicas, dramatización y banco de palabras por proyecto.","vivir":"Propiciar cuentos repetidos, lectura de imágenes, asambleas, noticia del día, objeto significativo, rimas, sílabas con palmas, sonidos iniciales, títeres, teatro de sombras y relatos de experiencias.","valorar":"Interpretar avances en narración, escucha, turnos, vocabulario, conciencia sonora y expresión emocional para ajustar secuencias visuales, objetos de apoyo, preguntas y dramatizaciones.","juego":"Tema: títeres, teatro de sombras, objeto significativo y juegos de sonidos. Competencia: espera turnos, dramatiza y conversa. Avance: relata eventos simples y participa en rimas. Evidencia: fotografía de dramatización.","exploracion":"Tema: experiencias familiares, colegio, barrio, naturaleza y objetos que provocan relatos. Competencia: observa, pregunta y conecta vivencias con palabras. Avance: describe situaciones y secuencias. Evidencia: dibujo narrado o registro anecdótico.","literatura":"Tema: cuentos repetidos, lectura de imágenes, rimas, adivinanzas, sílabas con palmas y sonidos iniciales. Competencia: escucha, anticipa, secuencia y juega con sonidos. Avance: responde preguntas básicas. Evidencia: audio autorizado.","arte":"Tema: dibujo narrativo, dramatización, música, máscaras y expresión corporal. Competencia: comunica historias con voz, cuerpo y material. Avance: representa inicio, desarrollo o cierre con apoyo. Evidencia: producción y registro de relato.","nucleos":"Narración; inicio-desarrollo-cierre; personajes; sonidos; rimas; turnos conversacionales.","saberes":"Preguntas qué/quién/dónde/por qué inicial; secuencias de 3 escenas; rimas, sonidos iniciales, onomatopeyas; vocabulario de familia, colegio, barrio y naturaleza.","competencias":"Narra experiencias; participa en conversaciones; usa expresiones gráficas, orales o corporales para comunicar; juega con sonidos.","evidencias":"Audio autorizado; cuento colectivo; dibujo narrado; registro anecdótico; fotografía de dramatización.","dua":"Secuencias visuales; objetos de apoyo; dictado al adulto; dramatización; pictogramas; opciones de respuesta.","caribe":"Relatos familiares, cuentos del Caribe, música, nombres propios, barrio, colegio, naturaleza y experiencias cotidianas como fuente de conversación, narración e identidad cultural.","gire":"Promover círculos seguros de palabra, respeto por emociones, cuidado de la voz, reconocimiento de adultos de confianza y uso de estrategias de calma ante frustración o dificultad para expresarse.","procesos":"Narración; escucha activa; turnos conversacionales; conciencia sonora inicial; ampliación de vocabulario; representación de historias con voz, cuerpo, dibujo y juego simbólico.","ambientes":"Rincones de lectura ventilados, asambleas breves, materiales visuales, títeres, objetos significativos, opciones de respuesta, pausas de calma y espacios emocionalmente seguros para hablar.","indicadores":"Relata eventos simples; escucha cuentos; espera turnos; responde preguntas; participa en rimas; juega con sonidos; representa historias con dibujo, cuerpo o dramatización.","documentacion":"Audio autorizado, dibujo narrado, cuento colectivo, registro anecdótico y fotografía de dramatización. Alertas: dificultades persistentes de comprensión, baja interacción verbal/no verbal, frustración frecuente al comunicarse, escasa atención a cuentos o sonidos; conversar con familia y ajustar apoyos.","emocional":"Escucha activa; expresión emocional; respeto de la palabra del otro; confianza para hablar.","familia":"Lectura diaria 10–12 minutos; audio/video corto del niño contando algo; rimas con nombres; libro viajero.","observacion":"Se observa cómo las niñas y los niños relatan eventos simples, esperan turnos, participan en rimas, escuchan cuentos, responden preguntas y representan historias con voz, cuerpo o dibujo. Estas evidencias permiten valorar avances en narración, escucha activa, vocabulario, conciencia sonora, expresión emocional y diálogo. A partir de lo observado, se ajustan secuencias visuales, objetos de apoyo, preguntas, dramatizaciones y oportunidades de conversación."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños se reconocen como narradores de experiencias, ideas y emociones, participan en conversaciones del grupo y fortalecen vínculos al escuchar y ser escuchados."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños usan lenguaje verbal y no verbal para describir, preguntar, responder, secuenciar, dialogar, dramatizar, cantar, jugar con sonidos y representar historias."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños disfrutan literatura, dramatización, música, rimas, cuentos, conversaciones y juegos sonoros como formas de explorar el lenguaje y comprender su mundo social y cultural."}]'::jsonb, '{"juego":{"tema":"títeres, teatro de sombras, objeto significativo y juegos de sonidos.","competencia":"espera turnos, dramatiza y conversa.","avance":"relata eventos simples y participa en rimas.","evidencia":"fotografía de dramatización."},"exploracion":{"tema":"experiencias familiares, colegio, barrio, naturaleza y objetos que provocan relatos.","competencia":"observa, pregunta y conecta vivencias con palabras.","avance":"describe situaciones y secuencias.","evidencia":"dibujo narrado o registro anecdótico."},"literatura":{"tema":"cuentos repetidos, lectura de imágenes, rimas, adivinanzas, sílabas con palmas y sonidos iniciales.","competencia":"escucha, anticipa, secuencia y juega con sonidos.","avance":"responde preguntas básicas.","evidencia":"audio autorizado."},"arte":{"tema":"dibujo narrativo, dramatización, música, máscaras y expresión corporal.","competencia":"comunica historias con voz, cuerpo y material.","avance":"representa inicio, desarrollo o cierre con apoyo.","evidencia":"producción y registro de relato."}}'::jsonb, 11)
