insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-S3-P3', 'step-3', 3, 'Periodo III', 'S3.3', 'Descubro patrones, números y formas en mi mundo', '{"alcance":"Consolidar pensamiento lógico-matemático inicial mediante clasificación, seriación, patrones, conteo hasta 10 con apoyo, correspondencia uno a uno, medición informal y retos con material concreto.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños fortalecen su identidad como pensadores capaces, cooperan con otros, comparten hallazgos y se sienten reconocidos por sus estrategias para organizar y comprender el entorno.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños describen criterios, procedimientos, comparaciones, patrones y cantidades mediante palabras, gestos, dibujos, construcciones, movimientos o material concreto.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños disfrutan juegos matemáticos, retos cotidianos, clasificación, seriación, patrones, conteo hasta 10 con apoyo, correspondencia uno a uno, medición informal y exploración de formas en su entorno.","indagar":"Observar conteo recitado y correspondencia, clasificación espontánea, seriación por tamaño, reconocimiento de formas, lenguaje comparativo, patrones y estrategias ante retos.","proyectar":"Diseñar ambientes de pensamiento lógico con rincones de conteo, patrones, geometría viva, medición informal, colecciones 1–10, figuras, recipientes, dados, tarjetas y estaciones manipulativas.","vivir":"Propiciar conteo en asistencia, pasos y reparto, juegos con dados, patrones AB/AAB/ABB con objetos y cuerpo, búsqueda de formas, medición con recipientes, organización de la mesa y resolución de rompecabezas.","valorar":"Interpretar estrategias usadas, lenguaje matemático emergente, cooperación, representación y transferencia a rutinas para ajustar materiales manipulativos, visuales numéricos, estaciones y niveles de complejidad.","juego":"Tema: dados, patrones AB/AAB/ABB, caza de formas, repartos y rompecabezas. Competencia: cuenta, clasifica, compara y crea secuencias. Avance: explica procedimientos simples con apoyo. Evidencia: fotografías de patrones y conteo.","exploracion":"Tema: números 1–10, formas, medidas informales, lleno/vacío, pesado/liviano, largo/corto. Competencia: organiza y compara el mundo concreto. Avance: transfiere nociones a rutinas. Evidencia: registro de reto matemático.","literatura":"Tema: cuentos acumulativos, canciones numéricas, rimas con patrones y relatos de problemas. Competencia: escucha secuencias, anticipa y verbaliza relaciones. Avance: usa lenguaje matemático emergente. Evidencia: conversación docente-niño.","arte":"Tema: patrones con cuerpo, objetos, color, ritmo y composición visual. Competencia: representa relaciones lógicas mediante material artístico. Avance: crea secuencias y clasificaciones visuales. Evidencia: producción o composición.","nucleos":"Patrones simples; ritmo; secuencias; conteo; correspondencia; formas; medición informal; clasificación.","saberes":"Números 1–10 con apoyo; muchos/pocos/ninguno; círculo, cuadrado, triángulo, rectángulo; lleno/vacío; pesado/liviano; largo/corto; más/menos.","competencias":"Reconoce patrones; clasifica con uno o dos criterios; cuenta con material concreto; explica procedimientos simples.","evidencias":"Fotografías de clasificaciones/patrones; registros de reto; producciones; conversación docente-niño.","dua":"Material manipulativo; visuales de número; opciones de respuesta; apoyo gestual; trabajo en estaciones; tiempos flexibles.","caribe":"Uso de objetos reales del entorno local: frutas, hojas, tapas, semillas, recipientes, bloques, agua y elementos cotidianos para clasificar, contar, medir y construir patrones.","gire":"Controlar piezas pequeñas, organizar estaciones manipulativas, usar recipientes estables, prevenir derrames o caídas, cuidar desplazamientos y mantener materiales limpios y seguros.","procesos":"Pensamiento lógico-matemático inicial; clasificación; seriación; patrones; conteo con apoyo; correspondencia uno a uno; medición informal; explicación de estrategias.","ambientes":"Estaciones manipulativas ventiladas, materiales seguros y limpios, recipientes estables, visuales numéricos, tiempos flexibles, pausas activas e hidratación.","indicadores":"Cuenta y reparte objetos; clasifica con uno o dos criterios; crea patrones; usa más/menos; compara tamaños; mide informalmente; explica procedimientos simples con apoyo.","documentacion":"Fotografías de patrones y clasificaciones, registros de reto, producciones y conversación docente-niño. Alertas: frustración persistente ante retos, dificultad marcada para manipular o seguir secuencias, baja participación en estaciones; ajustar complejidad y apoyos.","emocional":"Perseverancia; cooperación; valoración del error; respeto por estrategias de otros.","familia":"Contar escalones, frutas o juguetes; patrones con cucharas/legos; foto de clasificación en casa con frase del niño.","observacion":"Se observa cómo las niñas y los niños cuentan, reparten, crean patrones, clasifican por atributos, usan nociones de más/menos y justifican oralmente con apoyo. Estas evidencias permiten valorar avances en pensamiento lógico-matemático, lenguaje comparativo, resolución de retos, cooperación y representación. A partir de lo observado, se ajustan materiales manipulativos, visuales numéricos, estaciones, tiempos y niveles de complejidad."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños fortalecen su identidad como pensadores capaces, cooperan con otros, comparten hallazgos y se sienten reconocidos por sus estrategias para organizar y comprender el entorno."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños describen criterios, procedimientos, comparaciones, patrones y cantidades mediante palabras, gestos, dibujos, construcciones, movimientos o material concreto."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños disfrutan juegos matemáticos, retos cotidianos, clasificación, seriación, patrones, conteo hasta 10 con apoyo, correspondencia uno a uno, medición informal y exploración de formas en su entorno."}]'::jsonb, '{"juego":{"tema":"dados, patrones AB/AAB/ABB, caza de formas, repartos y rompecabezas.","competencia":"cuenta, clasifica, compara y crea secuencias.","avance":"explica procedimientos simples con apoyo.","evidencia":"fotografías de patrones y conteo."},"exploracion":{"tema":"números 1–10, formas, medidas informales, lleno/vacío, pesado/liviano, largo/corto.","competencia":"organiza y compara el mundo concreto.","avance":"transfiere nociones a rutinas.","evidencia":"registro de reto matemático."},"literatura":{"tema":"cuentos acumulativos, canciones numéricas, rimas con patrones y relatos de problemas.","competencia":"escucha secuencias, anticipa y verbaliza relaciones.","avance":"usa lenguaje matemático emergente.","evidencia":"conversación docente-niño."},"arte":{"tema":"patrones con cuerpo, objetos, color, ritmo y composición visual.","competencia":"representa relaciones lógicas mediante material artístico.","avance":"crea secuencias y clasificaciones visuales.","evidencia":"producción o composición."}}'::jsonb, 12)
