insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-S3-P4', 'step-3', 4, 'Periodo IV', 'S3.4', 'Juego con otros, me cuido y cuido mi mundo', '{"alcance":"Integrar habilidades socioemocionales, corporales, comunicativas y de cuidado del entorno mediante juego cooperativo, movimiento, arte, acuerdos de convivencia y proyectos de bienestar.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños se reconocen como miembros valiosos del grupo, participan en acuerdos, cooperan, cuidan de otros y fortalecen sentido de pertenencia a su aula, familia, colegio y entorno.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños expresan emociones, negocian turnos, resuelven conflictos simples con ayuda, piden perdón, agradecen, proponen acuerdos y representan vivencias mediante movimiento, danza, arte y juego.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños disfrutan experiencias de movimiento, juego cooperativo, arte, exploración del entorno, cuidado de plantas, reciclaje y retos colectivos de bienestar.","indagar":"Observar interacciones con pares, respuesta ante normas, reconocimiento emocional, habilidades motoras, uso de estrategias de calma y situaciones significativas de convivencia.","proyectar":"Diseñar ambientes de convivencia y cuidado con acuerdos visuales, rutinas de reparación, semáforo emocional, rincón de calma, juegos cooperativos, circuitos motores, danza y mini-proyectos de cuidado de plantas o reciclaje.","vivir":"Propiciar asambleas cortas, juegos por turnos, misiones en equipo, rondas, dramatización corporal, cuidado de plantas, acciones de reciclaje y conversaciones sobre reparación, calma y convivencia.","valorar":"Interpretar acuerdos, acciones de cuidado, estrategias de calma, cooperación y participación en proyectos para ajustar apoyos de convivencia, roles, reparación y proyectos de cuidado.","juego":"Tema: asambleas, semáforo emocional, juegos por turnos, misiones en equipo y rondas. Competencia: coopera, respeta acuerdos y repara. Avance: usa estrategias de calma con apoyo. Evidencia: registro de círculo de diálogo.","exploracion":"Tema: cuidado de plantas, agua, materiales, reciclaje y roles de aula. Competencia: observa consecuencias de sus acciones en el entorno. Avance: participa en acciones de cuidado. Evidencia: fotos de cuidado ambiental.","literatura":"Tema: cuentos de emociones, convivencia, reparación y cuidado del mundo. Competencia: identifica emociones, conflictos y soluciones. Avance: propone acuerdos o formas de reparar. Evidencia: conversación documentada.","arte":"Tema: dramatización corporal, danza, mural de acuerdos y producciones sobre cuidado. Competencia: expresa emociones y compromisos mediante cuerpo y materiales. Avance: participa en obra colectiva. Evidencia: mural o producción grupal.","nucleos":"Emociones; acuerdos; reparación; cooperación; cuidado de plantas; roles de aula; sostenibilidad inicial.","saberes":"Turno, pausa, reparación, cuidado; normas simples; respiración; roles; responsabilidad por materiales, plantas y agua.","competencias":"Reconoce emociones; coopera; repara; cuida materiales y entorno; participa en acuerdos.","evidencias":"Registro de círculo de diálogo; fotos de cuidado ambiental; acuerdos visibles; narrativas docentes.","dua":"Semáforo emocional; pictogramas de acuerdos; tarjetas de reparación; rincón de calma; roles claros.","caribe":"Cultura de cuidado en el aula y en Barranquilla: agua, sombra, plantas, residuos, patio, convivencia, cooperación, cuidado de pares y responsabilidad con el entorno cercano.","gire":"Reconocer acuerdos para desplazamientos, cuidar plantas y materiales, usar rutas de calma, prevenir conflictos, reparar daños, pedir ayuda y reconocer señales básicas de riesgo en el aula o patio.","procesos":"Autorregulación; convivencia; cooperación; reparación; cuidado del entorno; participación en acuerdos; responsabilidad inicial con materiales, plantas, agua y pares.","ambientes":"Ambientes con acuerdos visibles, rincón de calma, semáforo emocional, roles de cuidado, espacios ventilados, hidratación, proyectos de plantas o reciclaje y mediación respetuosa de conflictos.","indicadores":"Usa estrategias de calma con apoyo; respeta turnos; ayuda a pares; participa en acuerdos; cuida plantas, agua o materiales; propone formas de reparar; coopera en misiones de equipo.","documentacion":"Registro de círculos de diálogo, acuerdos visibles, fotografías de cuidado ambiental y narrativas docentes. Alertas: conflictos persistentes sin avance, dificultad sostenida para regularse, aislamiento, agresividad frecuente o rechazo de acuerdos; activar acompañamiento familia-escuela.","emocional":"Conciencia emocional; regulación; habilidades sociales; paz y convivencia.","familia":"Reforzar lenguaje de aula: turno, pausa, reparar, cuidar; compartir acciones de cuidado en casa.","observacion":"Se observa cómo las niñas y los niños usan estrategias de calma, ayudan a pares, respetan turnos, participan en acuerdos y realizan acciones de cuidado del entorno. Estas evidencias permiten valorar avances en autorregulación, cooperación, convivencia, reparación, responsabilidad y cuidado de la vida. A partir de lo observado, se ajustan acuerdos visuales, roles, tarjetas de reparación, espacios de calma y proyectos de cuidado."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños se reconocen como miembros valiosos del grupo, participan en acuerdos, cooperan, cuidan de otros y fortalecen sentido de pertenencia a su aula, familia, colegio y entorno."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños expresan emociones, negocian turnos, resuelven conflictos simples con ayuda, piden perdón, agradecen, proponen acuerdos y representan vivencias mediante movimiento, danza, arte y juego."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños disfrutan experiencias de movimiento, juego cooperativo, arte, exploración del entorno, cuidado de plantas, reciclaje y retos colectivos de bienestar."}]'::jsonb, '{"juego":{"tema":"asambleas, semáforo emocional, juegos por turnos, misiones en equipo y rondas.","competencia":"coopera, respeta acuerdos y repara.","avance":"usa estrategias de calma con apoyo.","evidencia":"registro de círculo de diálogo."},"exploracion":{"tema":"cuidado de plantas, agua, materiales, reciclaje y roles de aula.","competencia":"observa consecuencias de sus acciones en el entorno.","avance":"participa en acciones de cuidado.","evidencia":"fotos de cuidado ambiental."},"literatura":{"tema":"cuentos de emociones, convivencia, reparación y cuidado del mundo.","competencia":"identifica emociones, conflictos y soluciones.","avance":"propone acuerdos o formas de reparar.","evidencia":"conversación documentada."},"arte":{"tema":"dramatización corporal, danza, mural de acuerdos y producciones sobre cuidado.","competencia":"expresa emociones y compromisos mediante cuerpo y materiales.","avance":"participa en obra colectiva.","evidencia":"mural o producción grupal."}}'::jsonb, 13)
