insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-K-P1', 'kinder', 1, 'Periodo I', 'K.1', 'Investigo mi entorno con todos mis lenguajes', '{"alcance":"Desarrollar observación, pregunta, exploración, representación y pensamiento lógico mediante proyectos sobre el entorno natural, social y cultural.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños se reconocen como investigadores infantiles, capaces de preguntar, observar, proponer explicaciones y aportar a proyectos relacionados con su familia, cultura, naturaleza y comunidad.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños comunican hallazgos mediante oralidad, dibujo, construcción, juego, documentación, conversación, representación gráfica y socialización con pares, adultos y familias.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños participan en proyectos que vinculan naturaleza, cultura, arte, pensamiento lógico, observación, pregunta, clasificación, comparación y registro de cambios en el entorno.","indagar":"Observar intereses del grupo, preguntas sobre entorno natural, social y cultural, objetos traídos, cambios observados en naturaleza o comunidad, hipótesis infantiles y formas de registro.","proyectar":"Diseñar un ambiente de investigación con pregunta guía, roles, materiales de observación, salidas al patio o zona verde, recursos de registro, textos informativos y provocaciones artísticas.","vivir":"Propiciar observación, comparación, dibujo, construcción, clasificación, registro de cambios, entrevistas, exploración de naturaleza y cultura, socialización de hallazgos y representación de descubrimientos con múltiples lenguajes.","valorar":"Interpretar preguntas, registros, comparaciones, roles de investigación y socialización de hallazgos para ajustar preguntas guía, materiales, formas de registro y nuevas provocaciones del proyecto.","juego":"Tema: juego de investigadores, roles de observador, constructor, entrevistador y cuidador. Competencia: pregunta, observa, registra y coopera. Avance: asume roles en proyecto. Evidencia: registro de juego y bitácora.","exploracion":"Tema: entorno natural, social y cultural; cambios, objetos, comunidad y naturaleza. Competencia: compara, clasifica, formula hipótesis y explica. Avance: comunica hallazgos. Evidencia: documentación de proyecto.","literatura":"Tema: textos informativos, cuentos, relatos familiares y preguntas guía. Competencia: escucha, conversa, extrae ideas y amplía vocabulario. Avance: relaciona historias con investigación. Evidencia: conversación documentada.","arte":"Tema: dibujo de observación, construcción, mapas, modelado y exposición infantil. Competencia: representa hallazgos con múltiples lenguajes. Avance: produce registros gráficos o tridimensionales. Evidencia: bitácora, dibujos y exposición.","nucleos":"Observar; preguntar; registrar; comparar; explicar; socializar; múltiples lenguajes.","saberes":"Pregunta, hipótesis infantil, registro gráfico, clasificación, comparación, cambios, entorno natural/social/cultural.","competencias":"Formula preguntas; participa en proyectos; registra o representa hallazgos; comunica ideas con diversos lenguajes.","evidencias":"Bitácora de proyecto; dibujos; fotografías; conversaciones documentadas; exposición infantil.","dua":"Opciones de registro; material concreto; roles de participación; apoyos visuales; dictado al adulto.","caribe":"Proyectos sobre naturaleza, barrio, familia, cultura local, agua, clima, plantas, sonidos, oficios y comunidad barranquillera como punto de partida para investigar.","gire":"Realizar salidas al patio o zona verde con rutas seguras, roles definidos, hidratación, sombra, cuidado de plantas o insectos, reconocimiento de señales de protección y acompañamiento adulto permanente.","procesos":"Investigación infantil; observación; formulación de preguntas; hipótesis; comparación; registro; socialización; representación con múltiples lenguajes.","ambientes":"Ambientes de investigación ventilados, mesas de observación, lupas o materiales seguros, bitácoras, agua disponible, sombra, normas de cuidado, roles y estaciones organizadas.","indicadores":"Formula preguntas; observa cambios; registra mediante dibujo o marcas; compara objetos o fenómenos; asume roles; socializa hallazgos; propone explicaciones iniciales.","documentacion":"Bitácora de proyecto, dibujos, fotografías, conversaciones documentadas y exposición infantil. Alertas: baja participación sostenida, dificultad para observar o comunicar hallazgos, desregulación en salidas o proyectos; ajustar roles y activar conversación con familia.","emocional":"Confianza para investigar; respeto por hipótesis de otros; cooperación en proyectos.","familia":"Enviar historias, objetos o fotos; conversar sobre preguntas de investigación.","observacion":"Se observa cómo las niñas y los niños formulan preguntas, registran observaciones, comparan cambios, asumen roles de investigación y socializan hallazgos. Estas evidencias permiten valorar avances en curiosidad, pensamiento investigativo, comunicación, representación y cooperación. A partir de lo observado, se ajustan preguntas guía, materiales, roles, formas de registro y nuevas provocaciones del proyecto."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños se reconocen como investigadores infantiles, capaces de preguntar, observar, proponer explicaciones y aportar a proyectos relacionados con su familia, cultura, naturaleza y comunidad."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños comunican hallazgos mediante oralidad, dibujo, construcción, juego, documentación, conversación, representación gráfica y socialización con pares, adultos y familias."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños participan en proyectos que vinculan naturaleza, cultura, arte, pensamiento lógico, observación, pregunta, clasificación, comparación y registro de cambios en el entorno."}]'::jsonb, '{"juego":{"tema":"juego de investigadores, roles de observador, constructor, entrevistador y cuidador.","competencia":"pregunta, observa, registra y coopera.","avance":"asume roles en proyecto.","evidencia":"registro de juego y bitácora."},"exploracion":{"tema":"entorno natural, social y cultural; cambios, objetos, comunidad y naturaleza.","competencia":"compara, clasifica, formula hipótesis y explica.","avance":"comunica hallazgos.","evidencia":"documentación de proyecto."},"literatura":{"tema":"textos informativos, cuentos, relatos familiares y preguntas guía.","competencia":"escucha, conversa, extrae ideas y amplía vocabulario.","avance":"relaciona historias con investigación.","evidencia":"conversación documentada."},"arte":{"tema":"dibujo de observación, construcción, mapas, modelado y exposición infantil.","competencia":"representa hallazgos con múltiples lenguajes.","avance":"produce registros gráficos o tridimensionales.","evidencia":"bitácora, dibujos y exposición."}}'::jsonb, 14)
