insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-K-P2', 'kinder', 2, 'Periodo II', 'K.2', 'Las historias, los sonidos y las palabras nos conectan', '{"alcance":"Fortalecer lenguaje oral, comprensión, conciencia fonológica, literatura, narración y escritura emergente con intención comunicativa.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños viven la literatura como experiencia de vínculo, memoria, imaginación y pertenencia, conectando historias personales, familiares, culturales y del grupo.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños narran, describen, anticipan, juegan con sonidos, rimas y palabras, y usan marcas, dibujos, letras conocidas o dictado al adulto para comunicar ideas con intención.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños exploran cuentos, libros álbum, canciones, rimas, símbolos, nombres, palabras significativas y funciones sociales de la lectura y la escritura emergente.","indagar":"Observar cuentos favoritos, nombres propios, palabras significativas, juegos de sonidos, hipótesis sobre lectura y escritura, interés por personajes, rimas y mensajes del entorno.","proyectar":"Diseñar ambientes de literatura y escritura emergente con lectura dialógica, libros álbum, letras móviles, banco de palabras, rincones de escritura, dramatización, secuencias narrativas y apoyos gráficos.","vivir":"Propiciar lectura de cuentos, conversación sobre personajes, juegos con rimas, sílabas y sonidos iniciales, creación de cuentos colectivos, listas, carteles, mensajes, dibujos narrados y dramatizaciones.","valorar":"Interpretar comprensión, narración, conciencia sonora, escritura emergente e intención comunicativa para ajustar textos, preguntas, rincones de escritura, dramatizaciones y apoyos gráficos.","juego":"Tema: juegos de sonidos, rimas, sílabas, letras móviles, personajes y dramatización. Competencia: juega con lenguaje oral y escrito emergente. Avance: usa marcas o letras conocidas con intención. Evidencia: registro de juego.","exploracion":"Tema: nombres propios, palabras significativas, carteles, mensajes y textos del entorno. Competencia: interpreta usos sociales de la escritura. Avance: identifica marcas familiares. Evidencia: recorrido gráfico o portafolio.","literatura":"Tema: libros álbum, cuentos, rimas, secuencias, personajes, problema, emoción, solución y final. Competencia: comprende, narra y anticipa. Avance: crea relatos colectivos. Evidencia: cuento colectivo y audio autorizado.","arte":"Tema: dibujo narrado, dramatización, ilustración, escritura emergente y creación de carteles. Competencia: integra imagen, cuerpo, palabra y símbolo. Avance: comunica ideas con intención. Evidencia: producción gráfica.","nucleos":"Rimas; sílabas; sonidos iniciales; nombre propio; marcas; dictado al adulto; mensajes.","saberes":"Personajes, secuencia, problema, emoción, solución; función social del texto; escritura emergente; letras significativas; vocabulario narrativo.","competencias":"Narra historias; reconoce sonidos en juegos; usa escritura emergente con intención.","evidencias":"Cuento colectivo; escritura emergente; dibujos narrados; audios autorizados.","dua":"Letras móviles; dictado al adulto; imágenes secuenciales; dramatización; respuestas orales o gráficas.","caribe":"Cuentos, canciones, nombres, relatos familiares, oralidad Caribe, juegos de palabras, carteles del entorno, memoria cultural y mensajes cotidianos como base de lectura y escritura emergente.","gire":"Reconocer señales y mensajes del entorno escolar, cuidar materiales escritos, respetar turnos de lectura, usar espacios seguros de escucha y evitar presión lectoescritora que genere frustración o rechazo.","procesos":"Comprensión oral; narración; conciencia fonológica lúdica; literatura; escritura emergente; imaginación; representación con marcas, dibujos, letras conocidas y dictado al adulto.","ambientes":"Rincones de lectura ventilados, libros álbum, letras móviles seguras, materiales de escritura no tóxicos, pausas visuales, asambleas breves y espacios de expresión sin presión lectoescritora.","indicadores":"Narra con secuencia; participa en rimas; identifica sonidos iniciales en juegos; usa marcas o letras conocidas con intención; comenta personajes; crea mensajes, listas o carteles con apoyo.","documentacion":"Cuento colectivo, dibujos narrados, escrituras emergentes, audios autorizados y portafolio. Alertas: frustración intensa frente a lectura/escritura, dificultad persistente de comprensión o expresión, baja respuesta a sonidos del lenguaje; ajustar mediaciones y dialogar con familia.","emocional":"Identificación de emociones de personajes; escucha; expresión respetuosa.","familia":"Leer cuentos y conversar sobre inicio, problema, emoción, solución y final.","observacion":"Se observa cómo las niñas y los niños participan en rimas, usan marcas gráficas o letras conocidas, narran con secuencia, comentan personajes y comunican ideas con intención. Estas evidencias permiten valorar avances en lenguaje oral, comprensión, conciencia fonológica, escritura emergente, imaginación y representación. A partir de lo observado, se ajustan textos, preguntas, rincones de escritura, dramatizaciones y apoyos gráficos."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños viven la literatura como experiencia de vínculo, memoria, imaginación y pertenencia, conectando historias personales, familiares, culturales y del grupo."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños narran, describen, anticipan, juegan con sonidos, rimas y palabras, y usan marcas, dibujos, letras conocidas o dictado al adulto para comunicar ideas con intención."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños exploran cuentos, libros álbum, canciones, rimas, símbolos, nombres, palabras significativas y funciones sociales de la lectura y la escritura emergente."}]'::jsonb, '{"juego":{"tema":"juegos de sonidos, rimas, sílabas, letras móviles, personajes y dramatización.","competencia":"juega con lenguaje oral y escrito emergente.","avance":"usa marcas o letras conocidas con intención.","evidencia":"registro de juego."},"exploracion":{"tema":"nombres propios, palabras significativas, carteles, mensajes y textos del entorno.","competencia":"interpreta usos sociales de la escritura.","avance":"identifica marcas familiares.","evidencia":"recorrido gráfico o portafolio."},"literatura":{"tema":"libros álbum, cuentos, rimas, secuencias, personajes, problema, emoción, solución y final.","competencia":"comprende, narra y anticipa.","avance":"crea relatos colectivos.","evidencia":"cuento colectivo y audio autorizado."},"arte":{"tema":"dibujo narrado, dramatización, ilustración, escritura emergente y creación de carteles.","competencia":"integra imagen, cuerpo, palabra y símbolo.","avance":"comunica ideas con intención.","evidencia":"producción gráfica."}}'::jsonb, 15)
