insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-K-P3', 'kinder', 3, 'Periodo III', 'K.3', 'Construyo, cuento y resuelvo retos', '{"alcance":"Integrar nociones lógico-matemáticas, espaciales, temporales y grafomotoras en experiencias de juego, construcción, medición, conteo y solución de problemas.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños se reconocen capaces de resolver retos mediante exploración, ensayo, cooperación y participación en construcciones o desafíos compartidos.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños comunican estrategias para contar, comparar, clasificar, construir, medir, ubicarse y resolver problemas mediante palabras, dibujos, grafismos, construcciones, cuerpo o material concreto.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños usan cuerpo, material concreto, grafismo, juego, construcción, conteo, medición no convencional, seriación, patrones y retos cotidianos para comprender relaciones espaciales, temporales y lógico-matemáticas.","indagar":"Observar cómo cuentan, reparten, comparan, organizan materiales, construyen, miden, crean patrones, siguen secuencias y resuelven retos de construcción o movimiento.","proyectar":"Diseñar ambientes de construcción y resolución de problemas con estaciones de conteo, medición no convencional, seriación, patrones, mapas simples, retos cooperativos, visuales de pasos y roles de participación.","vivir":"Propiciar construcción de estructuras, reparto de materiales, medición con objetos, clasificación de colecciones, creación de patrones, recorridos, registro de resultados con dibujos o marcas y socialización de estrategias.","valorar":"Interpretar soluciones, cooperación, persistencia, estrategias de conteo, comparación, medición y construcción para ajustar retos, visuales de pasos, materiales y tiempos de trabajo.","juego":"Tema: estaciones de construcción, conteo, medición, patrones, mapas y retos cooperativos. Competencia: resuelve problemas con material concreto. Avance: explica estrategias y coopera. Evidencia: fotos de construcción.","exploracion":"Tema: cantidad, comparación, medida no convencional, ubicación, secuencia y correspondencia uno a uno. Competencia: prueba, compara y ajusta soluciones. Avance: transfiere nociones a rutinas. Evidencia: registro de estrategias.","literatura":"Tema: relatos de retos, instrucciones, cuentos de construcción y socialización de procedimientos. Competencia: escucha, explica y organiza verbalmente pasos. Avance: narra cómo resolvió. Evidencia: conversación docente-niño.","arte":"Tema: construcción, mapas simples, registro gráfico, trazos y diseño de soluciones. Competencia: representa estrategias con dibujos, marcas o estructuras. Avance: usa grafismo con sentido. Evidencia: producción o maqueta.","nucleos":"Conteo real; correspondencia; patrones; seriación; clasificación; ubicación; grafomotricidad.","saberes":"Cantidad, comparación, más/menos, largo/corto, pesado/liviano, posición, secuencia, patrón, correspondencia uno a uno, registro gráfico.","competencias":"Cuenta, compara, clasifica y resuelve retos con material concreto; coordina movimientos finos y gruesos.","evidencias":"Fotografías de construcciones; registro de estrategias; producciones; observación directa.","dua":"Material manipulativo; visual de pasos; roles; pausas activas; alternativas corporales.","caribe":"Retos con materiales reciclables, medidas del aula, recorridos, sombra, agua, plantas, objetos cotidianos y recursos del entorno local para construir, contar, medir y resolver problemas.","gire":"Garantizar seguridad en construcciones y recorridos, uso adecuado de cajas, bloques, recipientes y materiales manipulativos, organización de estaciones, cuidado postural y prevención de choques o caídas.","procesos":"Resolución de problemas; construcción; conteo real; medición no convencional; clasificación; seriación; patrones; ubicación espacial; registro de estrategias.","ambientes":"Espacios despejados para construir, materiales estables, agua disponible, pausas activas, visuales de pasos, roles cooperativos y cuidado de postura, desplazamiento y herramientas.","indicadores":"Resuelve problemas de reparto o construcción; compara, mide y clasifica; sigue secuencias; crea patrones; registra estrategias; coopera; explica cómo resolvió.","documentacion":"Fotografías de construcciones, registros de estrategias, producciones, observación directa y conversación docente-niño. Alertas: frustración persistente, dificultad para seguir secuencias, conductas de riesgo en construcción, baja cooperación sostenida; ajustar retos y apoyos.","emocional":"Persistencia; tolerancia a la frustración; pedir ayuda; cooperación.","familia":"Resolver retos cotidianos: repartir frutas, ordenar objetos, construir con bloques o cajas.","observacion":"Se observa cómo las niñas y los niños resuelven problemas de reparto o construcción, siguen secuencias, cooperan, comparan, miden, clasifican y representan estrategias. Estas evidencias permiten valorar avances en pensamiento lógico, resolución de problemas, grafomotricidad, cooperación y persistencia. A partir de lo observado, se ajustan retos, visuales de pasos, materiales manipulativos, roles y tiempos de trabajo."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños se reconocen capaces de resolver retos mediante exploración, ensayo, cooperación y participación en construcciones o desafíos compartidos."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños comunican estrategias para contar, comparar, clasificar, construir, medir, ubicarse y resolver problemas mediante palabras, dibujos, grafismos, construcciones, cuerpo o material concreto."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños usan cuerpo, material concreto, grafismo, juego, construcción, conteo, medición no convencional, seriación, patrones y retos cotidianos para comprender relaciones espaciales, temporales y lógico-matemáticas."}]'::jsonb, '{"juego":{"tema":"estaciones de construcción, conteo, medición, patrones, mapas y retos cooperativos.","competencia":"resuelve problemas con material concreto.","avance":"explica estrategias y coopera.","evidencia":"fotos de construcción."},"exploracion":{"tema":"cantidad, comparación, medida no convencional, ubicación, secuencia y correspondencia uno a uno.","competencia":"prueba, compara y ajusta soluciones.","avance":"transfiere nociones a rutinas.","evidencia":"registro de estrategias."},"literatura":{"tema":"relatos de retos, instrucciones, cuentos de construcción y socialización de procedimientos.","competencia":"escucha, explica y organiza verbalmente pasos.","avance":"narra cómo resolvió.","evidencia":"conversación docente-niño."},"arte":{"tema":"construcción, mapas simples, registro gráfico, trazos y diseño de soluciones.","competencia":"representa estrategias con dibujos, marcas o estructuras.","avance":"usa grafismo con sentido.","evidencia":"producción o maqueta."}}'::jsonb, 16)
