insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-K-P4', 'kinder', 4, 'Periodo IV', 'K.4', 'Convivo, cuido y preparo mi transición', '{"alcance":"Consolidar autonomía, regulación emocional, acuerdos, ciudadanía infantil, cuidado del entorno y preparación armónica hacia el grado de Transición.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños se reconocen como miembros activos del grupo, con responsabilidades, voz, acuerdos, vínculos y sentido de pertenencia, preparándose de manera armónica para nuevos retos escolares.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños usan estrategias de regulación, diálogo, reparación, expresión emocional, conversación, cuentos de transición, juego cooperativo y producciones simbólicas para comunicar lo que sienten y necesitan.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños cuidan materiales, compañeros, plantas y espacios, participan en proyectos de cuidado, rutinas de autonomía, responsabilidades de aula y experiencias que anticipan el paso a Transición.","indagar":"Observar emociones frente a nuevos retos, acuerdos conocidos, responsabilidades de aula, formas de cuidado del entorno, necesidades de apoyo y expectativas frente a Transición.","proyectar":"Diseñar ambientes de transición y convivencia con acuerdos visibles, roles cooperativos, caja de soluciones, cuentos de transición, responsabilidades de aula, proyecto de cuidado, carpeta de logros y apoyos de regulación.","vivir":"Propiciar círculos de diálogo, juegos cooperativos, rutinas de autonomía, cuidado ambiental, resolución de conflictos con mediación, responsabilidades de aula, carpeta de logros y experiencias de cierre.","valorar":"Interpretar logros, acuerdos, estrategias de regulación, responsabilidades y necesidades de apoyo para fortalecer autonomía, convivencia, cuidado y preparación hacia Transición.","juego":"Tema: juegos cooperativos, roles de aula, caja de soluciones y responsabilidades. Competencia: participa en acuerdos, pide ayuda y repara. Avance: asume responsabilidades con guía. Evidencia: registro de roles.","exploracion":"Tema: cuidado del entorno, materiales, plantas, pertenencias y nuevos retos escolares. Competencia: reconoce acciones de cuidado y consecuencias. Avance: propone formas de cuidar. Evidencia: fotografías de responsabilidades.","literatura":"Tema: cuentos de transición, emociones, convivencia, autonomía y cuidado. Competencia: conversa sobre cambios, emociones y soluciones. Avance: expresa expectativas y necesidades. Evidencia: registro de círculo de diálogo.","arte":"Tema: carpeta de logros, mural de acuerdos, símbolo de transición y producciones de cierre. Competencia: representa avances y pertenencia. Avance: selecciona evidencias significativas. Evidencia: carpeta o mural.","nucleos":"Acuerdos; reparación; roles; cuidado del entorno; autonomía escolar; transición.","saberes":"Turnos, responsabilidad, pedir ayuda, autocuidado, cuidado de pertenencias, reparación, lenguaje emocional, normas de convivencia.","competencias":"Participa en acuerdos; usa estrategias de regulación; cuida materiales y compañeros.","evidencias":"Acuerdos de aula; registro de círculos; fotografías de responsabilidades; narrativas docentes.","dua":"Acuerdos visibles; tarjetas de reparación; rincón de calma; roles cooperativos; lenguaje común.","caribe":"Cuidado del aula, patio, plantas, agua, pertenencias y compañeros en contexto de clima cálido, fortaleciendo sentido de pertenencia y preparación para nuevos retos escolares.","gire":"Usar rutas de calma, acuerdos visibles, señales de evacuación simples, pedir ayuda, cuidar desplazamientos, anticipar transiciones y reconocer adultos de apoyo ante malestar, conflicto o riesgo.","procesos":"Autonomía; regulación emocional; acuerdos; responsabilidades; cuidado del entorno; ciudadanía infantil; preparación armónica hacia Transición.","ambientes":"Ambientes con acuerdos visibles, roles de aula, caja de soluciones, rincón de calma, hidratación, rutinas de autocuidado, carpeta de logros y espacios de cierre emocional.","indicadores":"Pide ayuda; repara conflictos simples; asume responsabilidades; cuida materiales; participa en acuerdos; expresa expectativas frente a Transición; usa estrategias de regulación con guía.","documentacion":"Registro de círculos, carpeta de logros, fotografías de responsabilidades, acuerdos visibles y narrativas docentes. Alertas: ansiedad persistente ante cambios, conflictos frecuentes, dificultad sostenida para asumir rutinas, señales de malestar emocional; conversar con familia y planear apoyos.","emocional":"Regulación; habilidades sociales; paz; autocuidado; ciudadanía infantil.","familia":"Reforzar autonomía en casa; compartir evidencias de cuidado, cooperación o responsabilidad.","observacion":"Se observa cómo las niñas y los niños resuelven conflictos simples, piden ayuda, reparan, asumen responsabilidades de aula, cuidan materiales y participan en acuerdos. Estas evidencias permiten valorar avances en autonomía, regulación, ciudadanía infantil, convivencia y preparación para Transición. A partir de lo observado, se ajustan rutinas, responsabilidades, apoyos emocionales, estrategias de reparación y comunicación con familias."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños se reconocen como miembros activos del grupo, con responsabilidades, voz, acuerdos, vínculos y sentido de pertenencia, preparándose de manera armónica para nuevos retos escolares."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños usan estrategias de regulación, diálogo, reparación, expresión emocional, conversación, cuentos de transición, juego cooperativo y producciones simbólicas para comunicar lo que sienten y necesitan."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños cuidan materiales, compañeros, plantas y espacios, participan en proyectos de cuidado, rutinas de autonomía, responsabilidades de aula y experiencias que anticipan el paso a Transición."}]'::jsonb, '{"juego":{"tema":"juegos cooperativos, roles de aula, caja de soluciones y responsabilidades.","competencia":"participa en acuerdos, pide ayuda y repara.","avance":"asume responsabilidades con guía.","evidencia":"registro de roles."},"exploracion":{"tema":"cuidado del entorno, materiales, plantas, pertenencias y nuevos retos escolares.","competencia":"reconoce acciones de cuidado y consecuencias.","avance":"propone formas de cuidar.","evidencia":"fotografías de responsabilidades."},"literatura":{"tema":"cuentos de transición, emociones, convivencia, autonomía y cuidado.","competencia":"conversa sobre cambios, emociones y soluciones.","avance":"expresa expectativas y necesidades.","evidencia":"registro de círculo de diálogo."},"arte":{"tema":"carpeta de logros, mural de acuerdos, símbolo de transición y producciones de cierre.","competencia":"representa avances y pertenencia.","avance":"selecciona evidencias significativas.","evidencia":"carpeta o mural."}}'::jsonb, 17)
