insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-T-P1', 'transicion', 1, 'Periodo I', 'T.1', 'Soy investigador: observo, pregunto y explico', '{"alcance":"Fortalecer habilidades de investigación infantil, observación, formulación de preguntas, pensamiento lógico, lenguaje explicativo y documentación de hallazgos.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños se reconocen como sujetos capaces de preguntar, investigar, aportar explicaciones y participar con seguridad en proyectos relacionados con su comunidad, naturaleza, ciudad, cuerpo u objetos.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños registran hallazgos mediante dibujos, marcas, mapas, listas, fotografías mediadas, construcciones, relatos y exposiciones, compartiendo ideas con escucha y cooperación.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños observan, comparan, miden informalmente, clasifican, experimentan, entrevistan, construyen hipótesis y socializan descubrimientos sobre fenómenos o situaciones del entorno.","indagar":"Observar preguntas del grupo, hipótesis infantiles, intereses sobre naturaleza, ciudad, cuerpo, objetos o comunidad, formas de observar, registrar y explicar hallazgos.","proyectar":"Diseñar un ambiente de investigación con pregunta guía, roles, estaciones, bitácora, materiales de observación, formas diversas de registro, textos informativos y apoyos visuales.","vivir":"Propiciar observación, comparación, medición informal, clasificación, experimentación, entrevistas, construcción de hipótesis, dibujo de mapas, elaboración de listas, registro de hallazgos y socialización de descubrimientos.","valorar":"Interpretar preguntas, hipótesis, registros, explicaciones, documentación y socialización de hallazgos para ajustar estaciones, roles, materiales de observación y formas de comunicación.","juego":"Tema: equipos de investigación, roles, estaciones, entrevistas y socialización. Competencia: organiza acciones, pregunta y coopera. Avance: sostiene una tarea investigativa. Evidencia: bitácora y registro de roles.","exploracion":"Tema: naturaleza, ciudad, cuerpo, objetos o comunidad; observación, comparación, medición informal y clasificación. Competencia: formula hipótesis y explica. Avance: contrasta ideas con evidencias. Evidencia: registros gráficos.","literatura":"Tema: textos informativos, preguntas, relatos de descubrimiento y exposición oral. Competencia: escucha información, formula preguntas y comunica hallazgos. Avance: explica con mayor claridad. Evidencia: exposición documentada.","arte":"Tema: mapas, dibujos de observación, diagramas infantiles, construcciones y documentación visual. Competencia: registra y representa hallazgos. Avance: usa símbolos, marcas o dibujos con intención. Evidencia: bitácora artística.","nucleos":"Pregunta; hipótesis infantil; observación; registro; comparación; socialización.","saberes":"Pregunta investigativa, hipótesis, registro gráfico, comparación, clasificación, explicación inicial, exposición oral con apoyo.","competencias":"Observa, pregunta, registra y comunica hallazgos de investigación infantil.","evidencias":"Bitácora de investigación; registros gráficos; exposición; documentación pedagógica.","dua":"Opciones de registro; dictado al adulto; apoyos visuales; trabajo por estaciones; roles.","caribe":"Investigaciones sobre ciudad, naturaleza, cuerpo, objetos, agua, clima, cultura barranquillera, comunidad, familia y fenómenos del entorno cercano.","gire":"Organizar exploraciones con roles, rutas seguras, hidratación, sombra, cuidado de recursos naturales, uso responsable de materiales de observación y reconocimiento de señales de protección.","procesos":"Investigación infantil; pregunta; hipótesis; observación sistemática; registro gráfico; comparación; medición informal; explicación y socialización de hallazgos.","ambientes":"Estaciones de investigación seguras, bitácoras, materiales limpios, objetos de observación no peligrosos, ventilación, pausas, roles cooperativos y normas de cuidado.","indicadores":"Formula preguntas; propone hipótesis; observa y registra; clasifica; mide informalmente; entrevista; comunica hallazgos con mayor seguridad; contrasta ideas con evidencias.","documentacion":"Bitácora de investigación, registros gráficos, exposición, documentación pedagógica y fotografías mediadas. Alertas: dificultad persistente para comunicar, baja participación sostenida, desregulación en proyectos o riesgo en manipulación de materiales; ajustar apoyos y dialogar con familia.","emocional":"Confianza para explicar; escucha; cooperación; valoración del error como aprendizaje.","familia":"Aportar preguntas, objetos, relatos o fotos para investigación; conversar sobre hallazgos.","observacion":"Se observa cómo las niñas y los niños formulan preguntas, proponen explicaciones iniciales, registran con dibujos, marcas o fotografías mediadas, y comunican hallazgos con mayor seguridad. Estas evidencias permiten valorar avances en investigación infantil, pensamiento lógico, lenguaje explicativo, documentación y cooperación. A partir de lo observado, se ajustan preguntas, estaciones, roles, materiales de observación y formas de socialización."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños se reconocen como sujetos capaces de preguntar, investigar, aportar explicaciones y participar con seguridad en proyectos relacionados con su comunidad, naturaleza, ciudad, cuerpo u objetos."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños registran hallazgos mediante dibujos, marcas, mapas, listas, fotografías mediadas, construcciones, relatos y exposiciones, compartiendo ideas con escucha y cooperación."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños observan, comparan, miden informalmente, clasifican, experimentan, entrevistan, construyen hipótesis y socializan descubrimientos sobre fenómenos o situaciones del entorno."}]'::jsonb, '{"juego":{"tema":"equipos de investigación, roles, estaciones, entrevistas y socialización.","competencia":"organiza acciones, pregunta y coopera.","avance":"sostiene una tarea investigativa.","evidencia":"bitácora y registro de roles."},"exploracion":{"tema":"naturaleza, ciudad, cuerpo, objetos o comunidad; observación, comparación, medición informal y clasificación.","competencia":"formula hipótesis y explica.","avance":"contrasta ideas con evidencias.","evidencia":"registros gráficos."},"literatura":{"tema":"textos informativos, preguntas, relatos de descubrimiento y exposición oral.","competencia":"escucha información, formula preguntas y comunica hallazgos.","avance":"explica con mayor claridad.","evidencia":"exposición documentada."},"arte":{"tema":"mapas, dibujos de observación, diagramas infantiles, construcciones y documentación visual.","competencia":"registra y representa hallazgos.","avance":"usa símbolos, marcas o dibujos con intención.","evidencia":"bitácora artística."}}'::jsonb, 18)
