insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-T-P2', 'transicion', 2, 'Periodo II', 'T.2', 'Leo el mundo, narro y escribo con intención', '{"alcance":"Potenciar comprensión, narración, conciencia fonológica, escritura emergente y comunicación con sentido en situaciones reales de lectura, escritura, juego y representación.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños reconocen que sus historias, emociones, nombres, palabras familiares y producciones escritas emergentes tienen valor dentro del grupo, la familia y la cultura.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños comprenden historias, imágenes y situaciones; identifican personajes, emociones, problemas y soluciones; narran, explican, conversan y usan escritura emergente, dibujos, símbolos o letras conocidas para comunicar ideas con intención.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños exploran textos, cuentos, listas, carteles, mensajes, rimas, sílabas, sonidos iniciales y finales, reconociendo usos significativos de la lectura y la escritura en su entorno.","indagar":"Observar hipótesis sobre textos, palabras significativas, nombre propio, cuentos favoritos, formas de escribir mensajes, comprensión de historias y uso social de lectura y escritura.","proyectar":"Diseñar ambientes de lectura, escritura emergente y representación con libros álbum, secuencias, letras móviles, trazos multisensoriales, cuentos colectivos, listas, carteles, dictado al adulto y opciones de expresión oral, gráfica o corporal.","vivir":"Propiciar lectura de cuentos, conversaciones, dramatizaciones, identificación de sonidos, rimas y sílabas, creación de listas, carteles, mensajes, cuentos colectivos, dibujos narrados y textos con intención comunicativa.","valorar":"Interpretar producciones, relatos, hipótesis de escritura, comprensión de textos y uso de símbolos para ajustar experiencias de lectura, escritura emergente, dictado al adulto y juegos sonoros.","juego":"Tema: juegos de letras, sonidos, mensajes, roles de lector/escritor y dramatización. Competencia: usa símbolos en situaciones significativas. Avance: escribe o interpreta marcas con intención. Evidencia: registro de juego.","exploracion":"Tema: textos del entorno, listas, carteles, nombres, mensajes y señales. Competencia: comprende funciones sociales de lectura y escritura. Avance: produce mensajes funcionales. Evidencia: colección de textos.","literatura":"Tema: cuentos, poemas, cartas, libros álbum, recetas, noticias del aula y cuentos colectivos. Competencia: comprende, narra, dicta y conversa. Avance: participa en escritura colectiva. Evidencia: texto colectivo.","arte":"Tema: libro artesanal, ilustración, teatro, dibujo narrado y trazos multisensoriales. Competencia: integra imagen, palabra, cuerpo y símbolo. Avance: comunica historias con recursos diversos. Evidencia: libro o puesta en escena.","nucleos":"Nombre propio; listas; carteles; cuentos colectivos; rimas; sílabas; sonidos iniciales/finales.","saberes":"Comprensión de personajes, secuencia, causa, emoción, problema, solución; escritura emergente; conciencia fonológica lúdica.","competencias":"Narra, explica y conversa; usa escritura emergente para comunicar; participa en juegos sonoros.","evidencias":"Cuentos colectivos; listas; carteles; dibujos narrados; audios autorizados; portafolio.","dua":"Letras móviles; trazos multisensoriales; dictado al adulto; opción oral, gráfica o corporal.","caribe":"Textos del entorno Caribe: nombres, carteles, listas, cuentos, recetas, canciones, relatos familiares, mensajes de aula, cultura oral y palabras significativas de la comunidad.","gire":"Leer señales del entorno escolar, producir mensajes de cuidado, usar rutas visuales, comunicar necesidades, respetar turnos y evitar presión lectoescritora que afecte la seguridad emocional.","procesos":"Comprensión de textos e imágenes; narración; conversación; conciencia fonológica; escritura emergente; producción de mensajes; representación simbólica con intención comunicativa.","ambientes":"Ambientes de lectura y escritura emergente con libros, carteles, letras móviles, trazos multisensoriales, buena iluminación, ventilación, pausas, respeto por ritmos y ausencia de presión lectoescritora.","indicadores":"Relata historias; identifica personajes, emociones, problemas y soluciones; usa marcas, símbolos o letras conocidas; reconoce sonidos en juegos; dicta al adulto; produce mensajes con intención.","documentacion":"Portafolio, cuentos colectivos, listas, carteles, dibujos narrados y audios autorizados. Alertas: frustración intensa frente a lectura/escritura, dificultad persistente de comprensión, baja intención comunicativa o pérdida de avances; ajustar mediaciones y conversar con familia.","emocional":"Comprensión de emociones en relatos; expresión de ideas; respeto de turnos.","familia":"Leer cuentos; conversar sobre personajes, emociones, problemas y soluciones; compartir escrituras significativas.","observacion":"Se observa cómo las niñas y los niños relatan historias, usan marcas o letras con intención, reconocen sonidos en juegos orales, comprenden personajes, emociones, problemas y soluciones. Estas evidencias permiten valorar avances en oralidad, comprensión, conciencia fonológica, escritura emergente y comunicación con sentido. A partir de lo observado, se ajustan textos, dictado al adulto, apoyos gráficos, juegos sonoros y experiencias de producción escrita emergente."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños reconocen que sus historias, emociones, nombres, palabras familiares y producciones escritas emergentes tienen valor dentro del grupo, la familia y la cultura."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños comprenden historias, imágenes y situaciones; identifican personajes, emociones, problemas y soluciones; narran, explican, conversan y usan escritura emergente, dibujos, símbolos o letras conocidas para comunicar ideas con intención."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños exploran textos, cuentos, listas, carteles, mensajes, rimas, sílabas, sonidos iniciales y finales, reconociendo usos significativos de la lectura y la escritura en su entorno."}]'::jsonb, '{"juego":{"tema":"juegos de letras, sonidos, mensajes, roles de lector/escritor y dramatización.","competencia":"usa símbolos en situaciones significativas.","avance":"escribe o interpreta marcas con intención.","evidencia":"registro de juego."},"exploracion":{"tema":"textos del entorno, listas, carteles, nombres, mensajes y señales.","competencia":"comprende funciones sociales de lectura y escritura.","avance":"produce mensajes funcionales.","evidencia":"colección de textos."},"literatura":{"tema":"cuentos, poemas, cartas, libros álbum, recetas, noticias del aula y cuentos colectivos.","competencia":"comprende, narra, dicta y conversa.","avance":"participa en escritura colectiva.","evidencia":"texto colectivo."},"arte":{"tema":"libro artesanal, ilustración, teatro, dibujo narrado y trazos multisensoriales.","competencia":"integra imagen, palabra, cuerpo y símbolo.","avance":"comunica historias con recursos diversos.","evidencia":"libro o puesta en escena."}}'::jsonb, 19)
