insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-T-P3', 'transicion', 3, 'Periodo III', 'T.3', 'Resuelvo retos de la vida cotidiana', '{"alcance":"Integrar pensamiento lógico-matemático, resolución de problemas, medición, conteo, patrones, ubicación espacial, cooperación y explicación de estrategias en situaciones cotidianas.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños se reconocen capaces de resolver problemas cotidianos, colaborar con otros, compartir estrategias y sentirse parte de una comunidad que piensa, ensaya y aprende junta.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños explican estrategias, escuchan las de otros, representan soluciones con material concreto, cuerpo, dibujos, registros, palabras, números emergentes o construcciones.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños resuelven retos mediante conteo, comparación, clasificación, seriación, medición concreta, patrones, ubicación espacial, reparto y experimentación con situaciones reales.","indagar":"Observar cómo reparten, comparan, miden, ordenan, construyen, crean patrones, se ubican espacialmente, siguen pasos y resuelven problemas cotidianos.","proyectar":"Diseñar ambientes de resolución de problemas con retos por estaciones, material concreto, temporizador visual, recipientes, objetos de medición no convencional, registros gráficos, roles cooperativos y visuales de pasos.","vivir":"Propiciar retos de reparto, medición de ingredientes u objetos, clasificación, ordenamiento de secuencias, creación de patrones, construcción de recorridos, registro de estrategias y explicación de procedimientos.","valorar":"Interpretar procedimientos, cooperación, perseverancia, uso de conteo, comparación, medición, patrones y registros para ajustar retos, estaciones, apoyos visuales y oportunidades de explicación.","juego":"Tema: retos de reparto, medición, clasificación, patrones, recorridos y estaciones. Competencia: resuelve problemas con material concreto. Avance: explica estrategias y escucha otras. Evidencia: registro de reto.","exploracion":"Tema: conteo, correspondencia, seriación, patrones, medición no convencional, ubicación espacial y comparación. Competencia: usa relaciones matemáticas en situaciones reales. Avance: registra y compara soluciones. Evidencia: fotografías de estrategias.","literatura":"Tema: historias de problemas, instrucciones, recetas, relatos de procedimientos y socialización de soluciones. Competencia: comprende pasos y comunica procedimientos. Avance: explica cómo resolvió. Evidencia: conversación docente-niño.","arte":"Tema: registros gráficos, mapas, construcciones, diagramas y representación de soluciones. Competencia: representa estrategias mediante dibujo, marcas o materiales. Avance: organiza visualmente una solución. Evidencia: producción o construcción.","nucleos":"Conteo con sentido; correspondencia; seriación; patrones; medición no convencional; ubicación espacial.","saberes":"Conteo, correspondencia, seriación, patrones, medición no convencional, ubicación espacial, reparto, comparación y resolución de problemas.","competencias":"Resuelve problemas cotidianos usando conteo, comparación, clasificación, seriación o medición concreta.","evidencias":"Registro de retos; fotografías de estrategias; construcciones; producciones; conversación docente-niño.","dua":"Material concreto; visual de pasos; temporizador visual; roles; pausas activas; trabajo por estaciones.","caribe":"Retos de la vida cotidiana en casa, aula y ciudad: repartir, medir, ordenar, construir, ubicar rutas, cuidar agua, organizar materiales y resolver problemas reales.","gire":"Cuidar recorridos, recipientes, estaciones, materiales de medición y construcción; seguir pasos visuales; reconocer riesgos simples; organizar materiales; pedir ayuda y cuidar el cuerpo durante los retos.","procesos":"Pensamiento lógico-matemático; resolución de problemas cotidianos; conteo; comparación; clasificación; seriación; medición concreta; patrones; ubicación espacial; explicación de estrategias.","ambientes":"Ambientes de reto con material concreto, recipientes seguros, visuales de pasos, espacios despejados, hidratación, pausas activas, roles cooperativos y tiempos flexibles.","indicadores":"Usa estrategias de conteo; compara y clasifica; mide con objetos; crea patrones; resuelve repartos; registra soluciones; explica procedimientos; coopera y persevera ante el reto.","documentacion":"Registros de estrategias, fotografías de estaciones, producciones, conversación docente-niño y documentación de retos. Alertas: frustración persistente, dificultad sostenida para seguir pasos, baja tolerancia al error, conductas de riesgo con materiales; ajustar complejidad y apoyos.","emocional":"Perseverancia; tolerancia a la frustración; cooperación; pedir ayuda.","familia":"Resolver retos de reparto, medición o conteo en casa; preparar recetas sencillas o clasificar objetos.","observacion":"Se observa cómo las niñas y los niños usan estrategias de conteo, comparación, clasificación, seriación, medición concreta, patrones, ubicación espacial y registro para resolver retos cotidianos. Estas evidencias permiten valorar avances en pensamiento lógico-matemático, resolución de problemas, cooperación, explicación de procedimientos y perseverancia. A partir de lo observado, se ajustan retos, estaciones, materiales, apoyos visuales y oportunidades de socialización."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños se reconocen capaces de resolver problemas cotidianos, colaborar con otros, compartir estrategias y sentirse parte de una comunidad que piensa, ensaya y aprende junta."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños explican estrategias, escuchan las de otros, representan soluciones con material concreto, cuerpo, dibujos, registros, palabras, números emergentes o construcciones."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños resuelven retos mediante conteo, comparación, clasificación, seriación, medición concreta, patrones, ubicación espacial, reparto y experimentación con situaciones reales."}]'::jsonb, '{"juego":{"tema":"retos de reparto, medición, clasificación, patrones, recorridos y estaciones.","competencia":"resuelve problemas con material concreto.","avance":"explica estrategias y escucha otras.","evidencia":"registro de reto."},"exploracion":{"tema":"conteo, correspondencia, seriación, patrones, medición no convencional, ubicación espacial y comparación.","competencia":"usa relaciones matemáticas en situaciones reales.","avance":"registra y compara soluciones.","evidencia":"fotografías de estrategias."},"literatura":{"tema":"historias de problemas, instrucciones, recetas, relatos de procedimientos y socialización de soluciones.","competencia":"comprende pasos y comunica procedimientos.","avance":"explica cómo resolvió.","evidencia":"conversación docente-niño."},"arte":{"tema":"registros gráficos, mapas, construcciones, diagramas y representación de soluciones.","competencia":"representa estrategias mediante dibujo, marcas o materiales.","avance":"organiza visualmente una solución.","evidencia":"producción o construcción."}}'::jsonb, 20)
