insert into public.curriculum_experiences (version_id, id, level_id, period, period_label, period_code, title, fields, purposes, activities, source_row)
values ('ht-malla-2026-06', 'HT-T-P4', 'transicion', 4, 'Periodo IV', 'T.4', 'Me preparo para primaria cuidando de mí, de otros y del mundo', '{"alcance":"Consolidar autonomía, autorregulación, convivencia, cuidado, participación infantil y confianza para una transición segura hacia primaria.","propositos":"1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.\nEn esta experiencia se logra cuando las niñas y los niños reconocen fortalezas, apoyos, logros personales, vínculos y pertenencias que les permiten transitar con seguridad hacia primaria.\n\n2. Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.\nEn esta experiencia se logra cuando las niñas y los niños expresan emociones frente a la transición, piden ayuda, comunican necesidades, organizan materiales, narran logros, construyen su dossier de transición y representan lo aprendido mediante dibujos, relatos, símbolos o producciones.\n\n3. Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.\nEn esta experiencia se logra cuando las niñas y los niños participan en acuerdos, acciones de cuidado, cierre pedagógico, rutinas de autonomía, experiencias de anticipación de primaria y proyectos que fortalecen confianza, autorregulación y responsabilidad.","indagar":"Observar emociones frente a primaria, fortalezas, apoyos requeridos, responsabilidades, expectativas de niñas, niños y familias, y experiencias significativas del proceso vivido.","proyectar":"Diseñar ambientes y mediaciones de transición con cuentos, visitas o simulaciones, visuales de pasos, ruta de calma, dossier de fortalezas, carpeta de logros, acuerdos familia-escuela y ritual de cierre.","vivir":"Propiciar organización de materiales, visita o simulación de primaria, construcción de carpeta de transición, práctica de estrategias de calma, responsabilidades progresivas y cierre pedagógico del proceso.","valorar":"Interpretar emociones frente a primaria, fortalezas, apoyos requeridos, responsabilidades y logros para orientar el cierre pedagógico, la transición segura y los acuerdos familia-escuela.","juego":"Tema: juegos de retos cooperativos, liderazgo infantil, simulación de primaria y organización de materiales. Competencia: regula, coopera y asume responsabilidades. Avance: pide ayuda y persevera. Evidencia: registro de cierre.","exploracion":"Tema: cambios, crecimiento, nuevos espacios, responsabilidades, cuidado personal y ambiental. Competencia: compara pasado-presente-futuro y anticipa la transición. Avance: identifica apoyos y fortalezas. Evidencia: línea de tiempo o dossier.","literatura":"Tema: cuentos de transición, cartas, relatos de logros, emociones y despedida. Competencia: expresa recuerdos, expectativas y necesidades. Avance: construye relato de cierre. Evidencia: carta, audio o texto dictado.","arte":"Tema: carpeta de logros, símbolo de cierre, exposición y dossier de transición. Competencia: selecciona, representa y explica producciones. Avance: reconoce avances propios. Evidencia: portafolio comentado.","nucleos":"Autonomía escolar; regulación; acuerdos; liderazgo infantil; cuidado ambiental; dossier de transición.","saberes":"Preparar morral, organizar materiales, pedir ayuda, autorregularse, cooperar, cuidar, reparar, cerrar ciclos y proyectar nuevos retos.","competencias":"Transita hacia primaria con seguridad; regula emociones; asume responsabilidades; coopera y cuida.","evidencias":"Dossier de transición; carpeta de logros; acuerdos; registros narrativos; evidencias familiares.","dua":"Cuentos de transición; anticipación; visitas; visual de pasos; ruta de calma; dossier de fortalezas.","caribe":"Preparación para primaria desde la identidad familiar, cultural y Caribe: relatos de logros, cuidado del cuerpo ante el clima, pertenencias, rutas escolares, acuerdos y red de apoyo.","gire":"Anticipar nuevos espacios, reconocer adultos de referencia, pedir ayuda, usar rutas de calma, cuidar desplazamientos, organizar pertenencias y activar acuerdos familia-escuela para una transición segura.","procesos":"Autonomía; autorregulación; pertenencia; cierre de ciclo; reconocimiento de fortalezas; participación infantil; responsabilidad; transición segura hacia primaria.","ambientes":"Ambiente de transición emocionalmente seguro, carpeta de logros, dossier de fortalezas, hidratación, rutinas de autocuidado, visuales de pasos, espacios de conversación y rituales de cierre.","indicadores":"Reconoce logros; expresa emociones frente a primaria; organiza materiales; pide ayuda; regula frustración con estrategias conocidas; asume responsabilidades; participa en acuerdos y cierre pedagógico.","documentacion":"Dossier de transición, carpeta de logros, registros narrativos, conversaciones con familia, producciones de cierre y observador individual. Alertas: ansiedad persistente, regresiones significativas, dificultad sostenida para separarse, organizarse o regularse, señales de malestar emocional; activar acuerdos familia-escuela y acompañamiento institucional.","emocional":"Autoconfianza; autorregulación; cuidado; cierre; pertenencia; transición segura.","familia":"Construir carpeta de transición: lo que aprendí, lo que disfruto, lo que me ayuda; reforzar rutinas de autonomía.","observacion":"Se observa cómo las niñas y los niños piden ayuda, regulan la frustración, cooperan, preparan materiales, reconocen logros, participan en el dossier de transición y expresan emociones frente al paso a primaria. Estas evidencias permiten valorar avances en autonomía, autorregulación, pertenencia, seguridad emocional y transición escolar. A partir de lo observado, se ajustan apoyos de anticipación, acuerdos familia-escuela, rutas de calma y orientaciones para primaria."}'::jsonb, '[{"number":1,"statement":"Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.","realization":"En esta experiencia se logra cuando las niñas y los niños reconocen fortalezas, apoyos, logros personales, vínculos y pertenencias que les permiten transitar con seguridad hacia primaria."},{"number":2,"statement":"Las niñas y los niños son comunicadores activos de sus ideas, sentimientos y emociones; expresan, imaginan y representan su realidad.","realization":"En esta experiencia se logra cuando las niñas y los niños expresan emociones frente a la transición, piden ayuda, comunican necesidades, organizan materiales, narran logros, construyen su dossier de transición y representan lo aprendido mediante dibujos, relatos, símbolos o producciones."},{"number":3,"statement":"Las niñas y los niños disfrutan aprender; exploran y se relacionan con el mundo para comprenderlo y construirlo.","realization":"En esta experiencia se logra cuando las niñas y los niños participan en acuerdos, acciones de cuidado, cierre pedagógico, rutinas de autonomía, experiencias de anticipación de primaria y proyectos que fortalecen confianza, autorregulación y responsabilidad."}]'::jsonb, '{"juego":{"tema":"juegos de retos cooperativos, liderazgo infantil, simulación de primaria y organización de materiales.","competencia":"regula, coopera y asume responsabilidades.","avance":"pide ayuda y persevera.","evidencia":"registro de cierre."},"exploracion":{"tema":"cambios, crecimiento, nuevos espacios, responsabilidades, cuidado personal y ambiental.","competencia":"compara pasado-presente-futuro y anticipa la transición.","avance":"identifica apoyos y fortalezas.","evidencia":"línea de tiempo o dossier."},"literatura":{"tema":"cuentos de transición, cartas, relatos de logros, emociones y despedida.","competencia":"expresa recuerdos, expectativas y necesidades.","avance":"construye relato de cierre.","evidencia":"carta, audio o texto dictado."},"arte":{"tema":"carpeta de logros, símbolo de cierre, exposición y dossier de transición.","competencia":"selecciona, representa y explica producciones.","avance":"reconoce avances propios.","evidencia":"portafolio comentado."}}'::jsonb, 21)
