insert into public.curriculum_chunks (curriculum_version, id, level_id, period, experience_id, section, subsection, content, tags, authority, source_reference, content_hash, status, updated_at)
values ('ht-malla-2026-06', 'HT-S1-P1-OBS', 'step-1', 1, 'HT-S1-P1', 'observacion', null, 'Se observa cómo las niñas y los niños señalan, miran, toman o entregan objetos, se desplazan con mayor seguridad, buscan al adulto como base de seguridad y responden a canciones o cuentos breves. Estas evidencias permiten valorar avances en vínculo, comunicación emergente, exploración sensorial y participación. A partir de lo observado, se ajustan apoyos, mediaciones o nuevas provocaciones según intereses, necesidades y ritmos individuales.', array['observacion', 'que observar', 'observar', 'valoracion', 'evaluacion cualitativa', 'evaluar', 'Descubro y exploro mi entorno']::text[], 'institutional', '{"file":"Malla_HT_Version_Final_Junio_2026.xlsx","sheet":"Malla ajustada","cell":"AG2"}'::jsonb, '19a0ba584c3cfd08', 'active', '2026-06-01')
