insert into public.curriculum_chunks (curriculum_version, id, level_id, period, experience_id, section, subsection, content, tags, authority, source_reference, content_hash, status, updated_at)
values ('ht-malla-2026-06', 'HT-S1-P4-OBS', 'step-1', 4, 'HT-S1-P4', 'observacion', null, 'Se observa cómo las niñas y los niños exploran, manipulan, agrupan, señalan atributos, participan en canciones numéricas y comparten hallazgos con el adulto mediante gestos, palabras o acciones. Estas evidencias permiten valorar avances en exploración del medio, comunicación emergente, organización inicial del pensamiento y participación en juego. A partir de lo observado, se ajustan materiales, consignas, apoyos o nuevas experiencias de clasificación y conteo cotidiano.', array['observacion', 'que observar', 'observar', 'valoracion', 'evaluacion cualitativa', 'evaluar', 'Juego, clasifico y entiendo mi entorno']::text[], 'institutional', '{"file":"Malla_HT_Version_Final_Junio_2026.xlsx","sheet":"Malla ajustada","cell":"AG5"}'::jsonb, 'db12eb5ee7758736', 'active', '2026-06-01')
