insert into public.curriculum_chunks (curriculum_version, id, level_id, period, experience_id, section, subsection, content, tags, authority, source_reference, content_hash, status, updated_at)
values ('ht-malla-2026-06', 'HT-S2-P1-OBS', 'step-2', 1, 'HT-S2-P1', 'observacion', null, 'Se observa cómo las niñas y los niños nombran, comparan, clasifican, siguen consignas simples y participan en conteo con material concreto. Estas evidencias permiten valorar avances en lenguaje, reconocimiento corporal, exploración sensoperceptiva, clasificación y uso de nociones en situaciones de juego. A partir de lo observado, se ajustan consignas, apoyos gestuales, materiales concretos y oportunidades de expresión verbal o no verbal.', array['observacion', 'que observar', 'observar', 'valoracion', 'evaluacion cualitativa', 'evaluar', 'Mi cuerpo explora, nombra y compara']::text[], 'institutional', '{"file":"Malla_HT_Version_Final_Junio_2026.xlsx","sheet":"Malla ajustada","cell":"AG6"}'::jsonb, '143cd6301bbc7643', 'active', '2026-06-01')
