insert into public.curriculum_chunks (curriculum_version, id, level_id, period, experience_id, section, subsection, content, tags, authority, source_reference, content_hash, status, updated_at)
values ('ht-malla-2026-06', 'HT-S2-P2-OBS', 'step-2', 2, 'HT-S2-P2', 'observacion', null, 'Se observa cómo las niñas y los niños siguen secuencias de uno o dos pasos, guardan materiales, piden ayuda, usan palabras de cortesía y participan en rutinas de cuidado. Estas evidencias permiten valorar avances en autonomía, comunicación funcional, organización del espacio y cooperación. A partir de lo observado, se ajustan pictogramas, anticipaciones, modelamientos, tiempos y responsabilidades cotidianas.', array['observacion', 'que observar', 'observar', 'valoracion', 'evaluacion cualitativa', 'evaluar', 'Mi cuerpo se organiza y se comunica con el entorno']::text[], 'institutional', '{"file":"Malla_HT_Version_Final_Junio_2026.xlsx","sheet":"Malla ajustada","cell":"AG7"}'::jsonb, 'f23b99660178cbd4', 'active', '2026-06-01')
