insert into public.curriculum_chunks (curriculum_version, id, level_id, period, experience_id, section, subsection, content, tags, authority, source_reference, content_hash, status, updated_at)
values ('ht-malla-2026-06', 'HT-S2-P3-OBS', 'step-2', 3, 'HT-S2-P3', 'observacion', null, 'Se observa cómo las niñas y los niños completan frases, nombran personajes, anticipan situaciones, cantan, riman, dramatizan o narran experiencias con apoyo. Estas evidencias permiten valorar avances en oralidad, comprensión, memoria, escucha, expresión emocional y participación en literatura. A partir de lo observado, se ajustan preguntas, apoyos visuales, cuentos, objetos narrativos y oportunidades de conversación.', array['observacion', 'que observar', 'observar', 'valoracion', 'evaluacion cualitativa', 'evaluar', 'Mis palabras cuentan lo que vivo']::text[], 'institutional', '{"file":"Malla_HT_Version_Final_Junio_2026.xlsx","sheet":"Malla ajustada","cell":"AG8"}'::jsonb, 'b70d585c4ed8e524', 'active', '2026-06-01')
