insert into public.curriculum_chunks (curriculum_version, id, level_id, period, experience_id, section, subsection, content, tags, authority, source_reference, content_hash, status, updated_at)
values ('ht-malla-2026-06', 'HT-S2-P4-OBS', 'step-2', 4, 'HT-S2-P4', 'observacion', null, 'Se observa cómo las niñas y los niños cuentan, reparten, esperan turnos breves, intentan soluciones, cooperan y participan en mini-proyectos. Estas evidencias permiten valorar avances en resolución de problemas simples, clasificación, conteo aplicado, comunicación de procedimientos y convivencia. A partir de lo observado, se ajustan roles, materiales, tiempos, apoyos para turnos y retos de mayor o menor complejidad.', array['observacion', 'que observar', 'observar', 'valoracion', 'evaluacion cualitativa', 'evaluar', 'Juego, organizo y resuelvo pequeños retos']::text[], 'institutional', '{"file":"Malla_HT_Version_Final_Junio_2026.xlsx","sheet":"Malla ajustada","cell":"AG9"}'::jsonb, 'de9d0c9e19a84a94', 'active', '2026-06-01')
