insert into public.curriculum_chunks (curriculum_version, id, level_id, period, experience_id, section, subsection, content, tags, authority, source_reference, content_hash, status, updated_at)
values ('ht-malla-2026-06', 'HT-S3-P2-OBS', 'step-3', 2, 'HT-S3-P2', 'observacion', null, 'Se observa cómo las niñas y los niños relatan eventos simples, esperan turnos, participan en rimas, escuchan cuentos, responden preguntas y representan historias con voz, cuerpo o dibujo. Estas evidencias permiten valorar avances en narración, escucha activa, vocabulario, conciencia sonora, expresión emocional y diálogo. A partir de lo observado, se ajustan secuencias visuales, objetos de apoyo, preguntas, dramatizaciones y oportunidades de conversación.', array['observacion', 'que observar', 'observar', 'valoracion', 'evaluacion cualitativa', 'evaluar', 'Hablo, escucho y narro lo que vivo']::text[], 'institutional', '{"file":"Malla_HT_Version_Final_Junio_2026.xlsx","sheet":"Malla ajustada","cell":"AG11"}'::jsonb, '92dd725818039dd6', 'active', '2026-06-01')
