insert into public.curriculum_chunks (curriculum_version, id, level_id, period, experience_id, section, subsection, content, tags, authority, source_reference, content_hash, status, updated_at)
values ('ht-malla-2026-06', 'HT-S3-P4-OBS', 'step-3', 4, 'HT-S3-P4', 'observacion', null, 'Se observa cómo las niñas y los niños usan estrategias de calma, ayudan a pares, respetan turnos, participan en acuerdos y realizan acciones de cuidado del entorno. Estas evidencias permiten valorar avances en autorregulación, cooperación, convivencia, reparación, responsabilidad y cuidado de la vida. A partir de lo observado, se ajustan acuerdos visuales, roles, tarjetas de reparación, espacios de calma y proyectos de cuidado.', array['observacion', 'que observar', 'observar', 'valoracion', 'evaluacion cualitativa', 'evaluar', 'Juego con otros, me cuido y cuido mi mundo']::text[], 'institutional', '{"file":"Malla_HT_Version_Final_Junio_2026.xlsx","sheet":"Malla ajustada","cell":"AG13"}'::jsonb, '2b37e21046785d12', 'active', '2026-06-01')
