insert into public.curriculum_chunks (curriculum_version, id, level_id, period, experience_id, section, subsection, content, tags, authority, source_reference, content_hash, status, updated_at)
values ('ht-malla-2026-06', 'HT-K-P1-OBS', 'kinder', 1, 'HT-K-P1', 'observacion', null, 'Se observa cómo las niñas y los niños formulan preguntas, registran observaciones, comparan cambios, asumen roles de investigación y socializan hallazgos. Estas evidencias permiten valorar avances en curiosidad, pensamiento investigativo, comunicación, representación y cooperación. A partir de lo observado, se ajustan preguntas guía, materiales, roles, formas de registro y nuevas provocaciones del proyecto.', array['observacion', 'que observar', 'observar', 'valoracion', 'evaluacion cualitativa', 'evaluar', 'Investigo mi entorno con todos mis lenguajes']::text[], 'institutional', '{"file":"Malla_HT_Version_Final_Junio_2026.xlsx","sheet":"Malla ajustada","cell":"AG14"}'::jsonb, 'd1bd122caf398f8d', 'active', '2026-06-01')
