insert into public.curriculum_chunks (curriculum_version, id, level_id, period, experience_id, section, subsection, content, tags, authority, source_reference, content_hash, status, updated_at)
values ('ht-malla-2026-06', 'HT-K-P2-OBS', 'kinder', 2, 'HT-K-P2', 'observacion', null, 'Se observa cómo las niñas y los niños participan en rimas, usan marcas gráficas o letras conocidas, narran con secuencia, comentan personajes y comunican ideas con intención. Estas evidencias permiten valorar avances en lenguaje oral, comprensión, conciencia fonológica, escritura emergente, imaginación y representación. A partir de lo observado, se ajustan textos, preguntas, rincones de escritura, dramatizaciones y apoyos gráficos.', array['observacion', 'que observar', 'observar', 'valoracion', 'evaluacion cualitativa', 'evaluar', 'Las historias, los sonidos y las palabras nos conectan']::text[], 'institutional', '{"file":"Malla_HT_Version_Final_Junio_2026.xlsx","sheet":"Malla ajustada","cell":"AG15"}'::jsonb, '46a799192a921ef3', 'active', '2026-06-01')
