insert into public.curriculum_chunks (curriculum_version, id, level_id, period, experience_id, section, subsection, content, tags, authority, source_reference, content_hash, status, updated_at)
values ('ht-malla-2026-06', 'HT-K-P3-OBS', 'kinder', 3, 'HT-K-P3', 'observacion', null, 'Se observa cómo las niñas y los niños resuelven problemas de reparto o construcción, siguen secuencias, cooperan, comparan, miden, clasifican y representan estrategias. Estas evidencias permiten valorar avances en pensamiento lógico, resolución de problemas, grafomotricidad, cooperación y persistencia. A partir de lo observado, se ajustan retos, visuales de pasos, materiales manipulativos, roles y tiempos de trabajo.', array['observacion', 'que observar', 'observar', 'valoracion', 'evaluacion cualitativa', 'evaluar', 'Construyo, cuento y resuelvo retos']::text[], 'institutional', '{"file":"Malla_HT_Version_Final_Junio_2026.xlsx","sheet":"Malla ajustada","cell":"AG16"}'::jsonb, '77849abcc241d08a', 'active', '2026-06-01')
