insert into public.curriculum_chunks (curriculum_version, id, level_id, period, experience_id, section, subsection, content, tags, authority, source_reference, content_hash, status, updated_at)
values ('ht-malla-2026-06', 'HT-K-P4-OBS', 'kinder', 4, 'HT-K-P4', 'observacion', null, 'Se observa cómo las niñas y los niños resuelven conflictos simples, piden ayuda, reparan, asumen responsabilidades de aula, cuidan materiales y participan en acuerdos. Estas evidencias permiten valorar avances en autonomía, regulación, ciudadanía infantil, convivencia y preparación para Transición. A partir de lo observado, se ajustan rutinas, responsabilidades, apoyos emocionales, estrategias de reparación y comunicación con familias.', array['observacion', 'que observar', 'observar', 'valoracion', 'evaluacion cualitativa', 'evaluar', 'Convivo, cuido y preparo mi transición']::text[], 'institutional', '{"file":"Malla_HT_Version_Final_Junio_2026.xlsx","sheet":"Malla ajustada","cell":"AG17"}'::jsonb, '13ea2175b29156af', 'active', '2026-06-01')
