insert into public.curriculum_chunks (curriculum_version, id, level_id, period, experience_id, section, subsection, content, tags, authority, source_reference, content_hash, status, updated_at)
values ('ht-malla-2026-06', 'HT-T-P1-OBS', 'transicion', 1, 'HT-T-P1', 'observacion', null, 'Se observa cómo las niñas y los niños formulan preguntas, proponen explicaciones iniciales, registran con dibujos, marcas o fotografías mediadas, y comunican hallazgos con mayor seguridad. Estas evidencias permiten valorar avances en investigación infantil, pensamiento lógico, lenguaje explicativo, documentación y cooperación. A partir de lo observado, se ajustan preguntas, estaciones, roles, materiales de observación y formas de socialización.', array['observacion', 'que observar', 'observar', 'valoracion', 'evaluacion cualitativa', 'evaluar', 'Soy investigador: observo, pregunto y explico']::text[], 'institutional', '{"file":"Malla_HT_Version_Final_Junio_2026.xlsx","sheet":"Malla ajustada","cell":"AG18"}'::jsonb, '6b13d7e6904176e1', 'active', '2026-06-01')
