insert into public.curriculum_chunks (curriculum_version, id, level_id, period, experience_id, section, subsection, content, tags, authority, source_reference, content_hash, status, updated_at)
values ('ht-malla-2026-06', 'HT-T-P2-OBS', 'transicion', 2, 'HT-T-P2', 'observacion', null, 'Se observa cómo las niñas y los niños relatan historias, usan marcas o letras con intención, reconocen sonidos en juegos orales, comprenden personajes, emociones, problemas y soluciones. Estas evidencias permiten valorar avances en oralidad, comprensión, conciencia fonológica, escritura emergente y comunicación con sentido. A partir de lo observado, se ajustan textos, dictado al adulto, apoyos gráficos, juegos sonoros y experiencias de producción escrita emergente.', array['observacion', 'que observar', 'observar', 'valoracion', 'evaluacion cualitativa', 'evaluar', 'Leo el mundo, narro y escribo con intención']::text[], 'institutional', '{"file":"Malla_HT_Version_Final_Junio_2026.xlsx","sheet":"Malla ajustada","cell":"AG19"}'::jsonb, 'dd0e8ced3b0887b1', 'active', '2026-06-01')
