insert into public.curriculum_chunks (curriculum_version, id, level_id, period, experience_id, section, subsection, content, tags, authority, source_reference, content_hash, status, updated_at)
values ('ht-malla-2026-06', 'HT-T-P3-PROP-01', 'transicion', 3, 'HT-T-P3', 'propositos', 'Propósito 1', '1. Las niñas y los niños construyen su identidad en relación con los otros; se sienten queridos y valoran positivamente pertenecer a una familia, cultura y mundo.
En esta experiencia se logra cuando las niñas y los niños se reconocen capaces de resolver problemas cotidianos, colaborar con otros, compartir estrategias y sentirse parte de una comunidad que piensa, ensaya y aprende junta.', array['propositos', 'proposito', 'intencion', 'que buscamos', 'identidad', 'comunicacion', 'aprender', 'Resuelvo retos de la vida cotidiana']::text[], 'institutional', '{"file":"Malla_HT_Version_Final_Junio_2026.xlsx","sheet":"Malla ajustada","cell":"K20"}'::jsonb, '713ce78afddf4a7c', 'active', '2026-06-01')
