insert into public.curriculum_chunks (curriculum_version, id, level_id, period, experience_id, section, subsection, content, tags, authority, source_reference, content_hash, status, updated_at)
values ('ht-malla-2026-06', 'HT-T-P3-OBS', 'transicion', 3, 'HT-T-P3', 'observacion', null, 'Se observa cómo las niñas y los niños usan estrategias de conteo, comparación, clasificación, seriación, medición concreta, patrones, ubicación espacial y registro para resolver retos cotidianos. Estas evidencias permiten valorar avances en pensamiento lógico-matemático, resolución de problemas, cooperación, explicación de procedimientos y perseverancia. A partir de lo observado, se ajustan retos, estaciones, materiales, apoyos visuales y oportunidades de socialización.', array['observacion', 'que observar', 'observar', 'valoracion', 'evaluacion cualitativa', 'evaluar', 'Resuelvo retos de la vida cotidiana']::text[], 'institutional', '{"file":"Malla_HT_Version_Final_Junio_2026.xlsx","sheet":"Malla ajustada","cell":"AG20"}'::jsonb, '13147cb0238974a3', 'active', '2026-06-01')
